  1:{question:'What is the form of government of the United States?',answers:['Republic','Constitution-based federal republic','Representative democracy'],words:7,short:'Republic'},
  2:{question:'What is the supreme law of the land?',answers:['(U.S.) Constitution'],words:4,short:'Constitution'},
  3:{question:'Name one thing the U.S. Constitution does.',answers:['Forms the government','Defines powers of government','Defines the parts of government','Protects the rights of the people'],words:6,short:'Forms the government'}
