function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));$('save-status').textContent='';}catch(e){$('save-status').textContent='Progress cannot be saved in this browser session. You can still use all activities.';}}
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=key=>$('art-'+key).innerHTML;
const currentLesson=()=>state.lessons[state.current];
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function answerOrder(count,right=0){const positions=Array.from({length:count},(_,i)=>i).filter(i=>i!==state.lastPosition);const target=positions[Math.floor(Math.random()*positions.length)];const order=shuffle(Array.from({length:count},(_,i)=>i).filter(i=>i!==right));order.splice(target,0,right);state.lastPosition=target;return order;}
function normalize(value){return value.toLowerCase().replace(/[-–]/g,' ').replace(/[^a-z ]/g,'').replace(/\s+/g,' ').trim();}
function validAnswer(value,q){if(q===3&&/\d/.test(value))return false;const v=normalize(value);if(q===3)return validConstitutionFunction(v);return q===1?['republic','a republic','constitution based federal republic','a constitution based federal republic','representative democracy','a representative democracy'].includes(v):['constitution','the constitution','us constitution','the us constitution','u s constitution','the u s constitution','united states constitution','the united states constitution'].includes(v);}
// Anchored phrases accept articles, verb agreement and equivalent word order,
// but never a lone keyword, negation, or rights/powers assigned to the wrong group.
function validConstitutionFunction(value){
 const v=value.replace(/^(?:(?:the )?(?:(?:us|u s|united states) )?constitution|it) /,'');
 return [
  /^(?:forms?|creates?|establish(?:es)?) (?:the |a )?(?:federal )?government$/,
  /^defines? (?:the )?powers? of (?:the )?government$/,
  /^defines? (?:the )?governments? powers?$/,
  /^defines? (?:the )?(?:three )?(?:parts|branches) of (?:the )?government$/,
  /^defines? (?:the )?governments? (?:parts|branches)$/,
  /^protects? (?:the )?rights of (?:the )?people$/,
  /^protects? (?:the )?peoples rights$/
 ].some(pattern=>pattern.test(v));
}
// Shared speech utility also supports the future multi-question interview module.
let speechToken=0,activeCourseUtterance=null;
function stopSpeech(){speechToken++;if(window.speechSynthesis)speechSynthesis.cancel();}
function speak(text,statusId){
 const status=$(statusId),token=++speechToken;
 if(!window.speechSynthesis||typeof window.SpeechSynthesisUtterance!=='function'){if(status)status.textContent='Audio is not available in this browser.';return;}
 speechSynthesis.cancel();speechSynthesis.resume();const utterance=new SpeechSynthesisUtterance(text);activeCourseUtterance=utterance;utterance.lang='en-US';utterance.rate=.9;
 const voices=speechSynthesis.getVoices();const american=voices.filter(v=>/^en[-_]US$/i.test(v.lang));
 const voice=american.find(v=>v.localService)||american[0];if(voice)utterance.voice=voice;
 utterance.onerror=e=>{if(token===speechToken&&!['canceled','interrupted'].includes(e.error)&&status)status.textContent='Audio could not play. Try an installed American English voice.';};
 if(status)status.textContent='';let started=false;utterance.onstart=()=>{started=true;};setTimeout(()=>{if(!started&&token===speechToken&&status)status.textContent='Audio did not start here. Open updated.html in Safari or Chrome for sound.';},4000);speechSynthesis.speak(utterance);
}
