 $('exercise').innerHTML=`<div class="exercise"><div class="prompt">${t.title}</div>${t.typing?`<p>${lessons[state.current].question}</p><input id="typed" class="field" autocomplete="off" placeholder="Type an accepted answer" aria-label="Type an accepted answer" value="${esc(a.selection)}">`:`<div class="choices">${a.order.map(i=>`<button class="choice ${a.selection===i?'selected':''}" data-choice="${i}">${t.opts[i]}</button>`).join('')}</div>`}<div id="feedback" aria-live="polite"></div></div>`;
 const update=()=>{$('practice-next').textContent=a.checked?(index===2?(validAnswer(String(a.selection),state.current)?(state.current===1?'Continue to Question 2 →':'Continue to Question 3 →'):'Check answer'):'Next activity →'):'Check answer';$('practice-next').disabled=t.typing?!String(a.selection).trim():a.selection==='';if(a.checked){const correct=t.typing?validAnswer(a.selection,state.current):a.selection===t.right;feedback('feedback',correct,(correct?'Correct! ':'Not quite. ')+t.why);}else $('feedback').textContent='';};
 if(t.typing)$('typed').oninput=e=>{a.selection=e.target.value;a.checked=false;update();$('practice-next').disabled=!a.selection.trim();};
 else document.querySelectorAll('#exercise .choice').forEach(b=>b.onclick=()=>{a.selection=Number(b.dataset.choice);a.checked=false;document.querySelectorAll('#exercise .choice').forEach(x=>x.classList.toggle('selected',x===b));update();});update();
