const lawLabels={constitution:'U.S. Constitution',federal:'Federal laws',state:'State laws'};
function hierarchyCorrect(l){return l.slots[0]==='constitution'&&new Set(l.slots.slice(1)).size===2&&l.slots.slice(1).every(x=>['federal','state'].includes(x));}
function renderHierarchy(){
 const l=currentLesson(),a=l.activities[1];$('practice-step').textContent='Practice 2 of 3 · Law Hierarchy Challenge';
 $('exercise').innerHTML='<div class="exercise"><h3>Which law belongs at the top?</h3><p>Drag a law to a place below. Or select a law, then tap or press Enter on a place. Put both other laws on the same lower level.</p><div class="choice-bank">'+['federal','constitution','state'].map(k=>`<button class="secondary" draggable="true" data-law="${k}" aria-pressed="${l.picked===k}">${lawLabels[k]}</button>`).join('')+'</div><p id="placement-status" role="status">'+(l.picked?'Selected: '+lawLabels[l.picked]+'. Choose a place.':'Select a law to begin.')+'</p><div class="law-hierarchy"><div class="hierarchy-top"><strong>Highest authority</strong>'+slot(0,l)+'</div><div class="hierarchy-arrow" aria-hidden="true">↓</div><div class="law-level"><div>'+slot(1,l)+'</div><div>'+slot(2,l)+'</div></div></div><p class="hierarchy-tip">Both federal and state laws must follow the U.S. Constitution.</p><div id="feedback" aria-live="polite"></div></div>';
 document.querySelectorAll('[data-law]').forEach(b=>{b.onclick=()=>{l.picked=b.dataset.law;document.querySelectorAll('[data-law]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('placement-status').textContent='Selected: '+lawLabels[l.picked]+'. Choose a place.';};b.ondragstart=e=>{e.dataTransfer.setData('text/plain',b.dataset.law);e.dataTransfer.effectAllowed='move';};});
 document.querySelectorAll('[data-slot]').forEach(b=>{const place=k=>{if(!Object.hasOwn(lawLabels,k))return;const target=Number(b.dataset.slot),previous=l.slots.indexOf(k),displaced=l.slots[target];if(previous>=0)l.slots[previous]=displaced;l.slots[target]=k;l.picked=null;a.checked=false;renderHierarchy();$(`law-slot-${target}`).focus();save();};b.onclick=()=>place(l.picked);b.ondragover=e=>{e.preventDefault();b.classList.add('drag-over');};b.ondragleave=()=>b.classList.remove('drag-over');b.ondrop=e=>{e.preventDefault();place(e.dataTransfer.getData('text/plain'));};});
 $('practice-next').textContent=a.checked&&hierarchyCorrect(l)?'Next activity →':'Check hierarchy';$('practice-next').disabled=l.slots.some(x=>!x);
 if(a.checked)feedback('feedback',hierarchyCorrect(l),hierarchyCorrect(l)?'Correct! The Constitution is above both federal and state laws.':'Not quite. Place the U.S. Constitution at the top. Federal laws and state laws share the lower level.');
}
function slot(i,l){return `<button class="drop-slot" id="law-slot-${i}" data-slot="${i}" aria-label="${i===0?'Top place':'Lower place '+i}: ${l.slots[i]?lawLabels[l.slots[i]]:'empty'}">${l.slots[i]?lawLabels[l.slots[i]]:(i===0?'Place the highest law here':'Place another law here')}</button>`;}
