// Versioned Q3 vocabulary attempts: orders are generated once, then persisted.
function blankQ3(){return {practiceVersion:2,words:Array(6).fill(''),picked:null,questionOrder:null,bankOrder:null,meaningOrder:null,meaningIndex:0,meanings:Array.from({length:6},()=>blankActivity())};}
function validPermutation(order,size){return Array.isArray(order)&&order.length===size&&new Set(order).size===size&&order.every(n=>Number.isInteger(n)&&n>=0&&n<size);}
function restoreQ3(old){
 const q=blankQ3();if(old?.practiceVersion!==2)return q;
 const words=['form','define','power','branch of government','right','protect'];
 q.words=q.words.map((_,i)=>words.includes(old.words?.[i])?old.words[i]:'');q.picked=words.includes(old.picked)?old.picked:null;
 for(const key of ['questionOrder','bankOrder','meaningOrder'])q[key]=validPermutation(old[key],6)?old[key]:null;
 q.meaningIndex=bounded(old.meaningIndex,5);q.meanings=q.meanings.map((a,i)=>{const oldAnswer=old.meanings?.[i]||{};return {...a,selection:[0,1,2].includes(oldAnswer.selection)?oldAnswer.selection:'',checked:!!oldAnswer.checked,order:validPermutation(oldAnswer.order,3)?oldAnswer.order:null};});return q;
}
const vocabularyBlanks=[
 {before:'To create a new group is to ',after:' it.',answer:'form',hint:'Form means to create or establish something.',choices:['To create or establish something.','To keep something safe.','To explain clearly what something means.']},
 {before:'To explain a word clearly is to ',after:' it.',answer:'define',hint:'Define means to explain clearly what something is or what it can do.',choices:['To explain clearly what something is or what it can do.','To create or establish something.','To keep someone safe from harm.']},
 {before:'Having the authority to make decisions means having ',after:'.',answer:'power',hint:'Power means the authority to make decisions or take action.',choices:['The authority to make decisions or take action.','A freedom or protection under the law.','One of the main parts of government.']},
 {before:'One main part of government, with its own responsibilities, is a ',after:'.',answer:'branch of government',hint:'A branch of government is one of its main parts, with its own responsibilities.',choices:['One of the main parts of government, with its own responsibilities.','A freedom that people have under the law.','The authority to make decisions or take action.']},
 {before:'A freedom or protection that people have under the law is a ',after:'.',answer:'right',hint:'A right is a freedom or protection that people have under the law.',choices:['A freedom or protection that people have under the law.','The authority to make decisions for others.','One of the main parts of government.']},
 {before:'To keep something safe from harm is to ',after:' it.',answer:'protect',hint:'Protect means to keep someone or something safe from harm or unfair treatment.',choices:['To keep someone or something safe.','To choose someone in an election.','To create or establish something.']}
];
// Select from all 720 permutations, excluding the original list and the previous
// attempt. Generate the bank separately and reject position-by-position matches.
function wordPermutations(values){if(!values.length)return [[]];return values.flatMap((value,i)=>wordPermutations(values.filter((_,j)=>i!==j)).map(rest=>[value,...rest]));}
const wordOrders=wordPermutations([0,1,2,3,4,5]);
function sameOrder(a,b){return Array.isArray(b)&&a.every((n,i)=>n===b[i]);}
function chooseOrder(previous=null,against=null){const choices=wordOrders.filter(order=>!sameOrder(order,[0,1,2,3,4,5])&&!sameOrder(order,previous)&&(!against||order.every((id,i)=>id!==against[i])));return [...choices[Math.floor(Math.random()*choices.length)]];}
function initializeQ3Attempt(q,previous=null){
 if(!q.questionOrder)q.questionOrder=chooseOrder(previous?.questionOrder);
 if(!q.bankOrder)q.bankOrder=chooseOrder(previous?.bankOrder,q.questionOrder);
 if(!q.meaningOrder)q.meaningOrder=chooseOrder(previous?.meaningOrder);
 for(const answer of q.meanings)if(!answer.order)answer.order=shuffle([0,1,2]);
 // Independent choice shuffles can repeat positions. Avoid only the degenerate
 // case where all six correct answers land in the very same position.
 const positions=q.meanings.map(a=>a.order.indexOf(0));
 if(new Set(positions).size===1&&!q.meanings.some(a=>a.checked)){
  const id=Math.floor(Math.random()*6),answer=q.meanings[id],from=positions[0],to=(from+1+Math.floor(Math.random()*2))%3;
  [answer.order[from],answer.order[to]]=[answer.order[to],answer.order[from]];
 }
}
function restartQ3Attempt(){const l=currentLesson(),previous=l.q3;l.q3=blankQ3();initializeQ3Attempt(l.q3,previous);l.practiceStep=0;save();renderPractice();topOfLesson();}
function attemptControls(){return '<div class="q3-attempt-controls"><button class="secondary" id="new-q3-attempt">New practice attempt</button><p>Start the vocabulary check again with a new order.</p></div>';}
function vocabularyDone(){return vocabularyBlanks.every((item,i)=>currentLesson().q3.words[i]===item.answer);}
function renderQuestion3Practice(){
 const l=currentLesson(),q=l.q3;if(l.practiceStep===1)l.practiceStep=2;initializeQ3Attempt(q);save();$('practice-back').textContent=l.practiceStep===0?'← Learn':'← Previous';
 if(l.practiceStep===0){
  $('practice-step').textContent='Practice 1 of 2 · Vocabulary Check';
  $('exercise').innerHTML='<div class="exercise"><h3>Choose a word for each blank</h3><p>Select a word, then select a blank. Use each word once. You can also use Tab and Enter or Space.</p><div class="choice-bank">'+q.bankOrder.map(id=>{const word=vocabularyBlanks[id].answer;return `<button class="secondary" data-bank-word="${word}" aria-pressed="${q.picked===word}">${word}</button>`;}).join('')+'</div><p id="word-placement-status" role="status">'+(q.picked?'Selected: '+q.picked+'. Choose a blank.':'Select a word to begin.')+'</p><ol class="vocabulary-blanks">'+q.questionOrder.map((id,position)=>{const item=vocabularyBlanks[id];return `<li>${item.before}<button class="blank-slot ${q.words[id]?(q.words[id]===item.answer?'correct':'incorrect'):''}" id="blank-${id}" data-blank="${id}" aria-label="Blank ${position+1}: ${q.words[id]||'empty'}">${q.words[id]||'______'}</button>${item.after}<div id="blank-feedback-${id}" aria-live="polite"></div></li>`;}).join('')+'</ol>'+attemptControls()+'</div>';
  document.querySelectorAll('[data-bank-word]').forEach(b=>b.onclick=()=>{q.picked=b.dataset.bankWord;document.querySelectorAll('[data-bank-word]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('word-placement-status').textContent='Selected: '+q.picked+'. Choose a blank.';});
  document.querySelectorAll('[data-blank]').forEach(b=>b.onclick=()=>{if(!q.picked){$('word-placement-status').textContent='First select a word from the word bank.';return;}const id=Number(b.dataset.blank);q.words[id]=q.picked;q.picked=null;renderQuestion3Practice();$('blank-'+id).focus({preventScroll:true});});
  vocabularyBlanks.forEach((item,id)=>{if(q.words[id])feedback('blank-feedback-'+id,q.words[id]===item.answer,(q.words[id]===item.answer?'Correct! ':'Try again. ')+item.hint);});
  $('new-q3-attempt').onclick=restartQ3Attempt;$('practice-next').disabled=!vocabularyDone();$('practice-next').textContent='Next activity →';return;
 }
 renderQuestion3Recall();
}

function renderQuestion3Recall(){
 const l=currentLesson(),a=l.activities[2];$('practice-step').textContent='Practice 2 of 2 · Answer the Official Question';
 $('exercise').innerHTML=`<div class="exercise"><h3>${lessons[3].question}</h3><p>Type one accepted answer.</p><input id="typed" class="field" autocomplete="off" aria-label="Type one accepted answer" placeholder="Type one accepted answer" value="${esc(a.selection)}"><div id="feedback" aria-live="polite"></div><div id="recall-accepted" class="${a.checked?'':'hidden'}"><p>Accepted answers — you only need one:</p><ul class="official-answers">${lessons[3].answers.map(x=>'<li>'+x+'</li>').join('')}</ul></div><div id="q3-completion" class="q3-completion hidden" role="status"><h3>Question 3 complete!</h3><p>Well done. Continue to Review 1 to answer Questions 1–3 again.</p></div></div>`;
 function update(){const correct=a.checked&&validAnswer(String(a.selection),3);$('recall-accepted').classList.toggle('hidden',!a.checked);$('q3-completion').classList.toggle('hidden',!correct);$('practice-next').textContent=correct?'Continue to Review 1 →':'Check answer';$('practice-next').disabled=!String(a.selection).trim();if(a.checked)feedback('feedback',correct,correct?'Correct! One accepted answer is enough.':'Not quite. Give one complete function of the Constitution. Use one of the accepted answers below.');else{$('feedback').className='';$('feedback').textContent='';}}
 $('typed').oninput=e=>{a.selection=e.target.value;a.checked=false;update();};update();
}
function advanceQuestion3Practice(){
 const l=currentLesson(),q=l.q3;
 if(l.practiceStep===0){if(vocabularyDone()){l.practiceStep=2;renderPractice();topOfLesson();}return;}

 const a=l.activities[2];if(a.checked&&validAnswer(String(a.selection),3)){openReview();return;}a.checked=true;if(validAnswer(String(a.selection),3)){l.completed=true;state.reviewUnlocked=true;updateNavigation();}renderQuestion3Recall();
}

$('practice-clear').onclick=()=>{
 const l=currentLesson(),index=l.practiceStep;
 if(state.current===3&&index===0){l.q3.words=Array(6).fill('');l.q3.picked=null;}
 else if(state.current===2&&index===0){l.matches={};}
 else{l.activities[index]={...l.activities[index],selection:'',checked:false};if(state.current===2&&index===1){l.slots=[null,null,null];l.picked=null;}if(index===2)l.completed=false;}
 renderPractice();save();$('clear-status').textContent='Answers cleared. You can try this activity again.';if($('typed'))$('typed').focus();
};
$('practice-back').onclick=()=>{const l=currentLesson();if(l.practiceStep===0)setMode('learn');else{l.practiceStep=state.current===3?0:l.practiceStep-1;renderPractice();}};
$('practice-next').onclick=()=>{if(state.current===3){advanceQuestion3Practice();return;}const l=currentLesson(),a=l.activities[l.practiceStep];if(state.current===2&&l.practiceStep===0){if(matchesDone(matchItems,l.matches)){l.practiceStep++;renderPractice();}return;}if(state.current===2&&l.practiceStep===1){if(a.checked&&hierarchyCorrect(l)){l.practiceStep++;renderPractice();}else{a.checked=true;renderHierarchy();}return;}if(!a.checked||(l.practiceStep===2&&!validAnswer(String(a.selection),state.current))){a.checked=true;if(l.practiceStep===2&&validAnswer(String(a.selection),state.current)){l.completed=true;}renderPractice();}else if(l.practiceStep<2){l.practiceStep++;renderPractice();}else{l.completed=true;if(state.current===1)openQuestion(2);else openQuestion(3);}};
['learn','practice'].forEach(n=>$('tab-'+n).onclick=()=>setMode(n));
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>openQuestion(Number(b.dataset.question)));
document.querySelectorAll('.review-link').forEach(b=>b.onclick=openReview);
$('course-select').onchange=e=>e.target.value==='review'?openReview():openQuestion(Number(e.target.value));
// Typed cumulative review follows Question 3. Older review data stays in storage.
function freshReviewRecall(){return {index:0,answers:[blankActivity(),blankActivity(),blankActivity()]};}
function restoreReviewRecall(old){const r=freshReviewRecall();r.index=bounded(old?.index,2);r.answers=r.answers.map((a,i)=>({ ...a,selection:typeof old?.answers?.[i]?.selection==='string'?old.answers[i].selection:'',checked:!!old?.answers?.[i]?.checked}));return r;}
function openReview(){if(!state.reviewUnlocked)return;stopSpeech();state.current='review';updateNavigation();renderReview();save();topOfLesson();}
function renderReview(){
 ['learn','practice','activity-question'].forEach(id=>$(id).classList.add('hidden'));document.querySelector('.tabs').classList.add('hidden');$('review').classList.remove('hidden');
 const r=state.review.recall||(state.review.recall=freshReviewRecall()),q=r.index+1,a=r.answers[r.index];
 const passed=i=>r.answers[i].checked&&validAnswer(r.answers[i].selection,i+1);
 const count=r.answers.filter((_,i)=>passed(i)).length;
 $('review').innerHTML=`<h2 class="review-heading">Review 1 — Questions 1–3</h2><p>Type one accepted answer for each question. You can also say your answer aloud if you like.</p><p id="review-progress">Question ${q} of 3 · ${count} of 3 correct</p><form id="review-form" class="exercise"><h3 id="review-question">${lessons[q].question}</h3><label for="review-typed">Your answer</label><input id="review-typed" class="field" autocomplete="off" aria-describedby="review-question" value="${esc(a.selection)}"><div id="review-feedback" aria-live="polite"></div><button class="primary" id="review-check" type="submit">Check answer</button><button class="secondary" id="review-clear" type="button">Clear answer</button></form><div class="foot"><button class="secondary" id="review-back">${q===1?'← Question 3 Practice':'← Previous question'}</button><button class="primary" id="review-next">Next question →</button></div><p id="review-complete" class="learn-note" role="status" hidden>Review complete — all 3 answers are correct!</p><button class="secondary" id="review-repeat">Start review again</button>`;
 function update(){const correct=passed(r.index),done=r.answers.every((_,i)=>passed(i));$('review-next').hidden=q===3;$('review-next').disabled=!correct;$('review-check').disabled=!a.selection.trim();$('review-complete').hidden=!done;$('review-progress').textContent=`Question ${q} of 3 · ${r.answers.filter((_,i)=>passed(i)).length} of 3 correct`;if(a.checked)feedback('review-feedback',correct,correct?'Correct! One accepted answer is enough.':'Not quite. Try again. Give one accepted answer to this question.');else{$('review-feedback').textContent='';$('review-feedback').className='';}save();}
 $('review-typed').oninput=e=>{a.selection=e.target.value;a.checked=false;update();};
 $('review-clear').onclick=()=>{a.selection='';a.checked=false;$('review-typed').value='';update();$('review-feedback').textContent='Answer cleared. Try this question again.';$('review-typed').focus();};
 $('review-form').onsubmit=e=>{e.preventDefault();a.checked=true;update();};
 $('review-next').onclick=()=>{if(!passed(r.index)||r.index===2)return;r.index++;renderReview();$('review-typed').focus();topOfLesson();};
 $('review-back').onclick=()=>{if(r.index===0){state.lessons[3].practiceStep=2;state.lessons[3].mode='practice';openQuestion(3);}else{r.index--;renderReview();topOfLesson();}};
 $('review-repeat').onclick=()=>{state.review.recall=freshReviewRecall();renderReview();topOfLesson();};update();
}
