const q=r.ids[r.index],a=r.answers[r.index];host.innerHTML=`<p class="step">Interview Practice · ${r.index+1} of 2${q===1?' · Review':''}</p><h2 class="official-question-heading">${q2AudioButton(lessons[q].question)}</h2><form id="q2-form"><label for="q2-input">Your answer</label><input class="field" id="q2-input" autocomplete="off" value="${esc(a.value)}"><p id="q2-feedback" role="status"></p><button class="primary" type="submit">Check Answer</button> <button class="secondary" id="q2-reveal" type="button">Show accepted answer${q===1?'s':''}</button><p id="q2-revealed"></p></form><div class="foot"><button class="secondary" id="q2-back">← Back to lesson</button><button class="primary" id="q2-next" ${a.correct?'':'disabled'}>${q===2?'Review Question 1 →':'Finish Practice'}</button></div>`;
