speak=function(text,statusId){const clip=courseAudioClip(text);if(!clip){speechBeforeRecordedAudio(text,statusId);return;}activeCoursePlayer?.stop();stopPronunciation();const status=$(statusId),audio=new Audio(clip.src);pronunciationAudio=audio;if(status)status.textContent='';audio.play().catch(()=>{if(status)status.textContent='Audio playback was blocked in this browser. Check the tab sound setting or open updated.html in Safari or Chrome.';});};
