setMode=function(mode,scroll=true){if(state.current!==3){modeBeforeQ3(mode,scroll);return;}stopSpeech();currentLesson().mode=mode;$('learn').classList.toggle('hidden',mode!=='learn');$('practice').classList.add('hidden');$('activity-question').classList.add('hidden');$('review').classList.toggle('hidden',mode==='learn');if(mode==='practice'){if(!state.q3Interview)newQ3Interview(false);renderQ3Interview();}save();if(scroll)topOfLesson();};
