function q3Continue(){stopSpeech();$('learn').classList.add('hidden');$('review').classList.remove('hidden');$('review').innerHTML='<h2 class="question">Question 4 is coming soon</h2><p>This course currently contains Questions 1–3. Your progress is saved.</p><div class="foot"><button class="secondary" id="q4-return">Return to Question 3</button><button class="secondary" id="q4-review">Practice Questions 1 and 2</button></div>';$('q4-return').onclick=()=>openQuestion(3);$('q4-review').onclick=()=>{newQ3Interview(true);renderQ3Interview();save();};}
function renderQ3Interview(){const r=state.q3Interview,host=$('review');if(r.complete){host.innerHTML='<h2>'+ (r.review?'Review complete':'Question 3 practice complete')+'</h2><p id="q3-score"></p><div class="q3-complete-actions"><button class="secondary" id="q3-review">'+(r.review?'Repeat review':'Practice Questions 1 and 2')+'</button><button class="primary" id="q3-continue">Continue to Question 4 →</button><button class="secondary" id="q3-previous">'+(r.review?'Return to Question 3':'Previous: Question 2')+'</button><button class="secondary" id="q3-repeat">Practice Again</button></div>';$('q3-score').textContent=r.answers.filter(a=>a.firstCorrect).length+' of '+r.ids.length+' correct on the first attempt.';$('q3-review').onclick=()=>{newQ3Interview(true);renderQ3Interview();save();};$('q3-continue').onclick=q3Continue;$('q3-previous').onclick=()=>openQuestion(r.review?3:2);$('q3-repeat').onclick=()=>{newQ3Interview(false);renderQ3Interview();save();};return;}
const q=r.ids[r.index],a=r.answers[r.index];host.innerHTML=`<p class="step">${r.review?'Optional review · '+(r.index+1)+' of 2':'Interview Practice'}</p><h2 class="official-question-heading">${q2AudioButton(lessons[q].question)}</h2><form id="q3-form"><label for="q3-input">Your answer</label><input id="q3-input" class="field" autocomplete="off" value="${esc(a.value)}"><p id="q3-feedback" role="status"></p><button class="primary" type="submit">Check Answer</button> <button class="secondary" id="q3-reveal" type="button">Show accepted answers</button><p id="q3-answers"></p></form><div class="foot"><button class="secondary" id="q3-back">← Back to lesson</button><button class="primary" id="q3-next" ${a.correct?'':'disabled'}>${r.review&&r.index===0?'Next question →':'Finish Practice'}</button></div>`;
host.querySelector('[data-say]').onclick=()=>speak(lessons[q].question,'q3-feedback');$('q3-input').oninput=e=>{a.value=e.target.value;a.correct=false;$('q3-next').disabled=true;$('q3-feedback').textContent='';save();};$('q3-form').onsubmit=e=>{e.preventDefault();if(!a.value.trim())return;const correct=q===3?validAnswer(a.value,3):validQ2Interview(a.value,q);q2Record(q,a,correct);feedback('q3-feedback',correct,correct?'Correct! One accepted answer is enough.':'Good effort. Try again, or show the accepted answers for help.');$('q3-next').disabled=!correct;if(correct){state.lessons[q].completed=true;if(q===3)state.reviewUnlocked=true;}save();};$('q3-reveal').onclick=()=>{a.revealed=true;renderAcceptedAnswers($('q3-answers'),lessons[q].answers);save();};if(a.revealed)renderAcceptedAnswers($('q3-answers'),lessons[q].answers);$('q3-back').onclick=()=>setMode('learn');$('q3-next').onclick=()=>{if(!a.correct)return;stopSpeech();if(r.index<r.ids.length-1)r.index++;else r.complete=true;save();renderQ3Interview();topOfLesson();};if(a.correct)feedback('q3-feedback',true,'Correct! One accepted answer is enough.');}



let selectedCourseVoice='recorded:samantha',availableCourseVoices=[],requestedCourseVoice='',activeBrowserUtterance=null,courseVoicesReady=false;
try{requestedCourseVoice=localStorage.getItem('citizenship-course-speech-voice-v2')||'';}catch(e){}
function courseAudioClip(text){if(text==='(U.S.) Constitution')text='U.S. Constitution';return embeddedCourseAudio[text];}
function loadCourseVoices(){
 const select=$('course-voice'),engine=window.speechSynthesis;if(!select)return;
 availableCourseVoices=engine?engine.getVoices().filter(v=>v.lang&&/^en[-_]US$/i.test(v.lang)&&! /^(Reed|Flo)(\b|\s|\()/i.test(v.name)&&! /^(Albert|Bad News|Bahh|Bells|Boing|Bubbles|Cellos|Wobble|Good News|Grandma|Grandpa|Jester|Junior|Organ|Superstar|Ralph|Trinoids|Whisper|Zarvox)\b/i.test(v.name)):[];
 const rank=v=>{const n=v.name.toLowerCase();return n.includes('samantha')?0:n.includes('ava')?1:n.includes('alex')?2:3;};availableCourseVoices.sort((a,b)=>rank(a)-rank(b)||a.name.localeCompare(b.name));
 const previous=selectedCourseVoice;select.replaceChildren();const recorded=document.createElement('option');recorded.value='recorded:samantha';recorded.textContent='Samantha — recorded fallback';select.appendChild(recorded);
 for(const v of availableCourseVoices){const option=document.createElement('option');option.value=v.name;option.textContent=v.name+' ('+v.lang+')';select.appendChild(option);}
 const target=requestedCourseVoice||(!courseVoicesReady?availableCourseVoices.find(v=>/samantha/i.test(v.name))?.name:previous);selectedCourseVoice=availableCourseVoices.some(v=>v.name===target)?target:'recorded:samantha';select.value=selectedCourseVoice;if(availableCourseVoices.length)courseVoicesReady=true;
 $('course-voice-status').textContent='';
}
function setupCourseVoice(){loadCourseVoices();$('course-voice').onfocus=loadCourseVoices;[250,1000,2500,5000].forEach(delay=>setTimeout(loadCourseVoices,delay));$('course-voice').onchange=()=>{const resume=activeCoursePlayer?.isPlaying?.();stopSpeech();selectedCourseVoice=$('course-voice').value;requestedCourseVoice=selectedCourseVoice;try{localStorage.setItem('citizenship-course-speech-voice-v2',selectedCourseVoice);}catch(e){}activeCoursePlayer?.refreshVoice?.(resume);};$('course-voice-preview').onclick=()=>speak(lessons[state.current]?.question||lessons[1].question,'course-voice-status');if(window.speechSynthesis){if(window.speechSynthesis.addEventListener)window.speechSynthesis.addEventListener('voiceschanged',loadCourseVoices);else window.speechSynthesis.onvoiceschanged=loadCourseVoices;}}
const recordedSpeechBeforeBrowserVoices=speak;
speak=function(text,statusId){
 stopSpeech();const voice=availableCourseVoices.find(v=>v.name===selectedCourseVoice);if(!voice){recordedSpeechBeforeBrowserVoices(text,statusId);return;}
 const status=$(statusId),engine=window.speechSynthesis;if(!engine||typeof window.SpeechSynthesisUtterance!=='function'){recordedSpeechBeforeBrowserVoices(text,statusId);return;}
 const utterance=new window.SpeechSynthesisUtterance(text);activeBrowserUtterance=utterance;configureCourseUtterance(utterance,voice);const token=++speechToken;let started=false;if(status)status.textContent='';utterance.onstart=()=>{started=true;};utterance.onend=()=>{if(activeBrowserUtterance===utterance)activeBrowserUtterance=null;};utterance.onerror=e=>{if(token!==speechToken||['canceled','interrupted'].includes(e.error))return;activeBrowserUtterance=null;if(status)status.textContent='The selected browser voice could not play. Choose another voice or Samantha — recorded fallback.';};engine.cancel();engine.resume();engine.speak(utterance);setTimeout(()=>{if(!started&&token===speechToken&&activeBrowserUtterance===utterance){engine.cancel();activeBrowserUtterance=null;if(status)status.textContent='The selected browser voice did not start. Choose another voice or Samantha — recorded fallback.';}},4000);
};

const courseArtAtlases={"original": "images/2f5198fb2f59a72720144ac60178fc91ef2d150f1268a2f5adc88aa6d718bc7f.png", "civic": "images/5793939d1b9535519044a8d723fc94097f0510bd1a28ebe20e5102254882bb2b.png"};

function hydrateCourseArtwork(scope){
 const coordinates={document:[0,0],capitol:[1,0],whitehouse:[2,0],court:[0,1],speech:[1,1],religion:[2,1],community:[0,0],playground:[1,0],ballot:[2,0],representatives:[0,1],traffic:[1,1],crown:[2,1]};
 scope.querySelectorAll('.wc-art,.watercolor-art').forEach(container=>{
  if(container.querySelector('img[data-course-art]'))return;
  const name=Object.keys(coordinates).find(key=>container.classList.contains(key));if(!name)return;
  const sheet=container.classList.contains('watercolor-art')||['document','capitol'].includes(name)?'original':'civic';const [column,row]=coordinates[name];
  const image=document.createElement('img');image.dataset.courseArt=sheet;image.alt='';image.src=courseArtAtlases[sheet];image.draggable=false;image.decoding='async';image.style.left=(-column*100)+'%';image.style.top=(-row*100)+'%';container.appendChild(image);
 });
}
