const q1Translations={"What is the form of government of the United States?": {"ru": "\u041a\u0430\u043a\u043e\u0432\u0430 \u0444\u043e\u0440\u043c\u0430 \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u043e\u0432?", "es": "\u00bfCu\u00e1l es la forma de gobierno de los Estados Unidos?"}, "Republic": {"ru": "\u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430", "es": "Rep\u00fablica"}, "Constitution-based federal republic": {"ru": "\u0424\u0435\u0434\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430, \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043d\u0430 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438", "es": "Rep\u00fablica federal basada en la Constituci\u00f3n"}, "Representative democracy": {"ru": "\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f", "es": "Democracia representativa"}, "You only need to give one answer in the interview.": {"ru": "\u041d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u043e\u0442\u0432\u0435\u0442.", "es": "Solo necesita dar una respuesta en la entrevista."}, "Vote": {"ru": "\u0413\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u0442\u044c", "es": "Votar"}, "Elect": {"ru": "\u0418\u0437\u0431\u0438\u0440\u0430\u0442\u044c", "es": "Elegir"}, "Representative": {"ru": "\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c", "es": "Representante"}, "Democracy": {"ru": "\u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f", "es": "Democracia"}, "Direct democracy": {"ru": "\u041f\u0440\u044f\u043c\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f", "es": "Democracia directa"}, "To make a choice in an election or decision.": {"ru": "\u0421\u0434\u0435\u043b\u0430\u0442\u044c \u0432\u044b\u0431\u043e\u0440 \u043d\u0430 \u0432\u044b\u0431\u043e\u0440\u0430\u0445 \u0438\u043b\u0438 \u043f\u0440\u0438 \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.", "es": "Hacer una elecci\u00f3n al votar o tomar una decisi\u00f3n."}, "Example: People vote for a candidate or on a new law.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u041b\u044e\u0434\u0438 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442 \u0437\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0430 \u0438\u043b\u0438 \u043f\u043e \u0432\u043e\u043f\u0440\u043e\u0441\u0443 \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u0430.", "es": "Ejemplo: Las personas votan por un candidato o sobre una nueva ley."}, "To choose someone for a position by voting.": {"ru": "\u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u043d\u0430 \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u0443\u0442\u0451\u043c \u0433\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u043d\u0438\u044f.", "es": "Elegir a una persona para un cargo mediante una votaci\u00f3n."}, "Example: Americans elect a president.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u044b \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430.", "es": "Ejemplo: Los estadounidenses eligen a un presidente."}, "A person people elect to speak and make government decisions for them.": {"ru": "\u0427\u0435\u043b\u043e\u0432\u0435\u043a, \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u043e\u043d \u0432\u044b\u0441\u0442\u0443\u043f\u0430\u043b \u043e\u0442 \u0438\u043c\u0435\u043d\u0438 \u043b\u044e\u0434\u0435\u0439 \u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u043b \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0432 \u0438\u0445 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u0430\u0445.", "es": "Una persona elegida para hablar y tomar decisiones de gobierno en nombre de la gente."}, "Example: Representatives make government decisions.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.", "es": "Ejemplo: Los representantes toman decisiones de gobierno."}, "A system of government in which the people have political power.": {"ru": "\u0421\u0438\u0441\u0442\u0435\u043c\u0430 \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u043b\u0430\u0441\u0442\u044c \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043d\u0430\u0440\u043e\u0434\u0443.", "es": "Un sistema de gobierno en el que el poder pol\u00edtico pertenece al pueblo."}, "Example: The United States is a democracy.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u2014 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f.", "es": "Ejemplo: Estados Unidos es una democracia."}, "A form of democracy in which people vote directly on laws or decisions.": {"ru": "\u0424\u043e\u0440\u043c\u0430 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442 \u043f\u043e \u0437\u0430\u043a\u043e\u043d\u0430\u043c \u0438\u043b\u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c.", "es": "Una forma de democracia en la que las personas votan directamente sobre leyes o decisiones."}, "Example: Everyone votes to decide whether to build a new playground in their park.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u0412\u0441\u0435 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u0440\u0435\u0448\u0438\u0442\u044c, \u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043b\u0438 \u043d\u043e\u0432\u0443\u044e \u0434\u0435\u0442\u0441\u043a\u0443\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0443 \u0432 \u0441\u0432\u043e\u0451\u043c \u043f\u0430\u0440\u043a\u0435.", "es": "Ejemplo: Todos votan para decidir si se construye un nuevo parque infantil en su parque."}, "A form of democracy in which people elect representatives to make government decisions.": {"ru": "\u0424\u043e\u0440\u043c\u0430 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u0434\u043b\u044f \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0440\u0435\u0448\u0435\u043d\u0438\u0439.", "es": "Una forma de democracia en la que la gente elige representantes para tomar decisiones de gobierno."}, "Example: The United States is a representative democracy.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u2014 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f.", "es": "Ejemplo: Estados Unidos es una democracia representativa."}, "People vote to choose representatives. Representatives decide whether to build a new playground.": {"ru": "\u041b\u044e\u0434\u0438 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439. \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0438 \u0440\u0435\u0448\u0430\u044e\u0442, \u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043b\u0438 \u043d\u043e\u0432\u0443\u044e \u0434\u0435\u0442\u0441\u043a\u0443\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0443.", "es": "La gente vota para elegir representantes. Los representantes deciden si se construye un nuevo parque infantil."}, "A form of government in which people elect representatives. The country does not have a king or queen.": {"ru": "\u0424\u043e\u0440\u043c\u0430 \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439. \u0412 \u0441\u0442\u0440\u0430\u043d\u0435 \u043d\u0435\u0442 \u043a\u043e\u0440\u043e\u043b\u044f \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u044b.", "es": "Una forma de gobierno en la que la gente elige representantes. El pa\u00eds no tiene rey ni reina."}, "Example: The United States is a republic.": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440: \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u2014 \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430.", "es": "Ejemplo: Estados Unidos es una rep\u00fablica."}, "Monarchy: A king or queen is the head of state. The position is usually passed down through a family.": {"ru": "\u041c\u043e\u043d\u0430\u0440\u0445\u0438\u044f: \u0413\u043b\u0430\u0432\u043e\u0439 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u043e\u0440\u043e\u043b\u044c \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430. \u042d\u0442\u0430 \u0434\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u044c \u043e\u0431\u044b\u0447\u043d\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u043f\u043e \u043d\u0430\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0443 \u0432 \u0441\u0435\u043c\u044c\u0435.", "es": "Monarqu\u00eda: Un rey o una reina es el jefe de Estado. El cargo suele transmitirse por herencia dentro de una familia."}, "Republic: The country has no king or queen. People elect representatives to govern.": {"ru": "\u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430: \u0412 \u0441\u0442\u0440\u0430\u043d\u0435 \u043d\u0435\u0442 \u043a\u043e\u0440\u043e\u043b\u044f \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u044b. \u041b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u0434\u043b\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0442\u0440\u0430\u043d\u043e\u0439.", "es": "Rep\u00fablica: El pa\u00eds no tiene rey ni reina. La gente elige representantes para gobernar."}, "Remember: The United States has an elected president, not a king or queen.": {"ru": "\u0417\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u0435: \u0412 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445 \u0435\u0441\u0442\u044c \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442, \u0430 \u043d\u0435 \u043a\u043e\u0440\u043e\u043b\u044c \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430.", "es": "Recuerde: Estados Unidos tiene un presidente elegido, no un rey ni una reina."}, "Words to Know": {"ru": "\u041f\u043e\u043b\u0435\u0437\u043d\u044b\u0435 \u0441\u043b\u043e\u0432\u0430", "es": "Vocabulario \u00fatil"}, "Understand the Answer": {"ru": "\u041f\u043e\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043e\u0442\u0432\u0435\u0442\u0430", "es": "Comprenda la respuesta"}, "Official accepted answers": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0435 \u043e\u0442\u0432\u0435\u0442\u044b", "es": "Respuestas oficiales aceptadas"}, "The United States": {"ru": "\u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b", "es": "Estados Unidos"}, "People elect leaders to make national laws.": {"ru": "\u041b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0434\u043b\u044f \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0441\u0442\u0440\u0430\u043d\u044b.", "es": "La gente elige a sus dirigentes para que elaboren las leyes nacionales."}, "Be specific at the interview": {"ru": "\u041e\u0442\u0432\u0435\u0447\u0430\u0439\u0442\u0435 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438", "es": "Sea espec\u00edfico en la entrevista"}, "\u2715 Democracy alone \u2014 too general": {"ru": "\u2715 \u0422\u043e\u043b\u044c\u043a\u043e \u00ab\u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f\u00bb \u2014 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043e\u0431\u0449\u0438\u0439 \u043e\u0442\u0432\u0435\u0442", "es": "\u2715 Solo \u00abdemocracia\u00bb es demasiado general"}, "\u2713 Representative democracy": {"ru": "\u2713 \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f", "es": "\u2713 Democracia representativa"}, "You only need ONE answer.": {"ru": "\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u041e\u0414\u041d\u041e\u0413\u041e \u043e\u0442\u0432\u0435\u0442\u0430.", "es": "Solo necesita UNA respuesta."}, "People vote for representatives.": {"ru": "\u041b\u044e\u0434\u0438 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442 \u0437\u0430 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439.", "es": "La gente vota por representantes."}, "The people elect representatives.": {"ru": "\u041b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439.", "es": "La gente elige representantes."}, "Representatives make government decisions.": {"ru": "\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.", "es": "Los representantes toman decisiones de gobierno."}, "New Playground": {"ru": "\u041d\u043e\u0432\u0430\u044f \u0434\u0435\u0442\u0441\u043a\u0430\u044f \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0430", "es": "Nuevo parque infantil"}, "Should we build a new playground?": {"ru": "\u0421\u0442\u043e\u0438\u0442 \u043b\u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043d\u043e\u0432\u0443\u044e \u0434\u0435\u0442\u0441\u043a\u0443\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0443?", "es": "\u00bfDebemos construir un nuevo parque infantil?"}, "YES / NO": {"ru": "\u0414\u0410 / \u041d\u0415\u0422", "es": "S\u00cd / NO"}, "VOTING \u2192 ELECTED": {"ru": "\u0413\u041e\u041b\u041e\u0421\u041e\u0412\u0410\u041d\u0418\u0415 \u2192 \u0418\u0417\u0411\u0420\u0410\u041d\u041d\u042b\u0419 \u041a\u0410\u041d\u0414\u0418\u0414\u0410\u0422", "es": "VOTACI\u00d3N \u2192 PERSONA ELEGIDA"}, "Democracy means people have a say in how their government works.": {"ru": "\u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u0432\u043b\u0438\u044f\u0442\u044c \u043d\u0430 \u0442\u043e, \u043a\u0430\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0438\u0445 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e.", "es": "La democracia significa que las personas tienen voz en el funcionamiento de su gobierno."}, "In a direct democracy, people vote directly on decisions. For example, everyone votes to decide whether to build a new playground in their park.": {"ru": "\u041f\u0440\u0438 \u043f\u0440\u044f\u043c\u043e\u0439 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438 \u043b\u044e\u0434\u0438 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442 \u043f\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c. \u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u0441\u0435 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u0440\u0435\u0448\u0438\u0442\u044c, \u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043b\u0438 \u043d\u043e\u0432\u0443\u044e \u0434\u0435\u0442\u0441\u043a\u0443\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0443 \u0432 \u0441\u0432\u043e\u0451\u043c \u043f\u0430\u0440\u043a\u0435.", "es": "En una democracia directa, las personas votan directamente sobre las decisiones. Por ejemplo, todos votan para decidir si se construye un nuevo parque infantil en su parque."}, "In a representative democracy, people elect representatives. Those representatives make many decisions for them.": {"ru": "\u041f\u0440\u0438 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438 \u043b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439. \u042d\u0442\u0438 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u043c\u043d\u043e\u0433\u0438\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e\u0442 \u0438\u0445 \u0438\u043c\u0435\u043d\u0438.", "es": "En una democracia representativa, la gente elige representantes. Esos representantes toman muchas decisiones en su nombre."}, "The United States is a representative democracy, not a direct democracy. Americans elect people to make national laws.": {"ru": "\u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u2014 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f, \u0430 \u043d\u0435 \u043f\u0440\u044f\u043c\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f. \u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u044b \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043b\u044e\u0434\u0435\u0439 \u0434\u043b\u044f \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0441\u0442\u0440\u0430\u043d\u044b.", "es": "Estados Unidos es una democracia representativa, no una democracia directa. Los estadounidenses eligen a personas para elaborar las leyes nacionales."}, "The United States is also a republic. It has no king or queen as head of state. People elect representatives to govern.": {"ru": "\u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u0442\u0430\u043a\u0436\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0439. \u0413\u043b\u0430\u0432\u043e\u0439 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u043e\u0440\u043e\u043b\u044c \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430. \u041b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u0434\u043b\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0442\u0440\u0430\u043d\u043e\u0439.", "es": "Estados Unidos tambi\u00e9n es una rep\u00fablica. No tiene un rey ni una reina como jefe de Estado. La gente elige representantes para gobernar."}, "\u201cDemocracy\u201d alone is too general for this USCIS question. Say \u201crepresentative democracy,\u201d or give another officially accepted answer.": {"ru": "\u041e\u0434\u043d\u043e\u0433\u043e \u0441\u043b\u043e\u0432\u0430 \u00ab\u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f\u00bb \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e: \u044d\u0442\u043e \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043e\u0431\u0449\u0438\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 USCIS. \u0421\u043a\u0430\u0436\u0438\u0442\u0435 \u00ab\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f\u00bb \u0438\u043b\u0438 \u0434\u0430\u0439\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u0439 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0439 \u043e\u0442\u0432\u0435\u0442.", "es": "Decir solo \u00abdemocracia\u00bb es demasiado general para esta pregunta de USCIS. Diga \u00abdemocracia representativa\u00bb o d\u00e9 otra respuesta oficial aceptada."}, "The official answers are: Republic. Constitution-based federal republic. Representative democracy. You only need one.": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043e\u0442\u0432\u0435\u0442\u044b: \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430; \u0444\u0435\u0434\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430, \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043d\u0430 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438; \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f. \u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043e\u0434\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430.", "es": "Las respuestas oficiales son: rep\u00fablica; rep\u00fablica federal basada en la Constituci\u00f3n; democracia representativa. Solo necesita una."}, "Monarchy \u2014 not the United States": {"ru": "\u041c\u043e\u043d\u0430\u0440\u0445\u0438\u044f \u2014 \u043d\u0435 \u0444\u043e\u0440\u043c\u0430 \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0421\u0428\u0410", "es": "Monarqu\u00eda \u2014 no es el sistema de Estados Unidos"}, "Republic \u2014 the United States": {"ru": "\u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430 \u2014 \u0444\u043e\u0440\u043c\u0430 \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0421\u0428\u0410", "es": "Rep\u00fablica \u2014 el sistema de Estados Unidos"}, "What is the supreme law of the land?": {"ru": "\u041a\u0430\u043a\u043e\u0439 \u0437\u0430\u043a\u043e\u043d \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0432\u044b\u0441\u0448\u0438\u043c \u0437\u0430\u043a\u043e\u043d\u043e\u043c \u0441\u0442\u0440\u0430\u043d\u044b?", "es": "\u00bfCu\u00e1l es la ley suprema del pa\u00eds?"}, "The (U.S.) Constitution": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f (\u0421\u0428\u0410)", "es": "La Constituci\u00f3n (de Estados Unidos)"}, "(U.S.) Constitution": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f (\u0421\u0428\u0410)", "es": "Constituci\u00f3n (de Estados Unidos)"}, "The Constitution.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f.", "es": "La Constituci\u00f3n."}, "You can simply answer: The Constitution.": {"ru": "\u041c\u043e\u0436\u043d\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c \u043f\u0440\u043e\u0441\u0442\u043e: \u00ab\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f\u00bb.", "es": "Puede responder simplemente: \u00abLa Constituci\u00f3n\u00bb."}, "Law": {"ru": "\u0417\u0430\u043a\u043e\u043d", "es": "Ley"}, "Supreme": {"ru": "\u0412\u044b\u0441\u0448\u0438\u0439", "es": "Supremo"}, "Supreme law": {"ru": "\u0412\u044b\u0441\u0448\u0438\u0439 \u0437\u0430\u043a\u043e\u043d", "es": "Ley suprema"}, "Constitution": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f", "es": "Constituci\u00f3n"}, "A rule made by the government that people must follow.": {"ru": "\u041f\u0440\u0430\u0432\u0438\u043b\u043e, \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u043e\u043c, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c.", "es": "Una norma establecida por el gobierno que las personas deben cumplir."}, "Highest or most important.": {"ru": "\u0421\u0430\u043c\u044b\u0439 \u0432\u044b\u0441\u043e\u043a\u0438\u0439 \u043f\u043e \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u0441\u0430\u043c\u044b\u0439 \u0432\u0430\u0436\u043d\u044b\u0439.", "es": "Lo m\u00e1s alto o lo m\u00e1s importante."}, "The law with the highest authority. Other laws cannot go against it.": {"ru": "\u0417\u0430\u043a\u043e\u043d, \u043e\u0431\u043b\u0430\u0434\u0430\u044e\u0449\u0438\u0439 \u0432\u044b\u0441\u0448\u0435\u0439 \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u0438\u043b\u043e\u0439. \u0414\u0440\u0443\u0433\u0438\u0435 \u0437\u0430\u043a\u043e\u043d\u044b \u043d\u0435 \u043c\u043e\u0433\u0443\u0442 \u0435\u043c\u0443 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0438\u0442\u044c.", "es": "La ley con la m\u00e1xima autoridad. Las dem\u00e1s leyes no pueden contradecirla."}, "A country's most important set of rules. It explains how the government works, what it can do, and what rights people have.": {"ru": "\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u0441\u0432\u043e\u0434 \u043f\u0440\u0430\u0432\u0438\u043b \u0441\u0442\u0440\u0430\u043d\u044b. \u041e\u043d \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0435\u0442, \u043a\u0430\u043a \u0443\u0441\u0442\u0440\u043e\u0435\u043d\u0430 \u0432\u043b\u0430\u0441\u0442\u044c, \u0447\u0442\u043e \u043e\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u043b\u0430\u0442\u044c \u0438 \u043a\u0430\u043a\u0438\u0435 \u043f\u0440\u0430\u0432\u0430 \u0435\u0441\u0442\u044c \u0443 \u043b\u044e\u0434\u0435\u0439.", "es": "El conjunto de normas m\u00e1s importantes de un pa\u00eds. Explica c\u00f3mo funciona el gobierno, qu\u00e9 puede hacer y qu\u00e9 derechos tienen las personas."}, "The United States has many laws": {"ru": "\u0412 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445 \u043c\u043d\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u043e\u0432", "es": "Estados Unidos tiene muchas leyes"}, "Laws are rules people must follow.": {"ru": "\u0417\u0430\u043a\u043e\u043d\u044b \u2014 \u044d\u0442\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u043b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c.", "es": "Las leyes son normas que las personas deben cumplir."}, "The highest legal authority": {"ru": "\u0412\u044b\u0441\u0448\u0430\u044f \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0441\u0438\u043b\u0430", "es": "La m\u00e1xima autoridad legal"}, "U.S. Constitution": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410", "es": "Constituci\u00f3n de Estados Unidos"}, "Above ordinary federal and state laws": {"ru": "\u0412\u044b\u0448\u0435 \u043e\u0431\u044b\u0447\u043d\u044b\u0445 \u0444\u0435\u0434\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0438 \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0448\u0442\u0430\u0442\u043e\u0432", "es": "Por encima de las leyes federales ordinarias y las leyes estatales"}, "Common mistake": {"ru": "\u0422\u0438\u043f\u0438\u0447\u043d\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430", "es": "Error com\u00fan"}, "Interview answer": {"ru": "\u041e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438", "es": "Respuesta en la entrevista"}, "Name one thing the U.S. Constitution does.": {"ru": "\u041d\u0430\u0437\u043e\u0432\u0438\u0442\u0435 \u043e\u0434\u043d\u0443 \u0438\u0437 \u0444\u0443\u043d\u043a\u0446\u0438\u0439 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u0421\u0428\u0410.", "es": "Mencione una funci\u00f3n de la Constituci\u00f3n de Estados Unidos."}, "Forms the government": {"ru": "\u0423\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0432\u043b\u0430\u0441\u0442\u0438", "es": "Establece el gobierno"}, "Defines powers of government": {"ru": "\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f \u043e\u0440\u0433\u0430\u043d\u043e\u0432 \u0432\u043b\u0430\u0441\u0442\u0438", "es": "Define los poderes del gobierno"}, "Defines the parts of government": {"ru": "\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u043e\u0440\u0433\u0430\u043d\u043e\u0432 \u0432\u043b\u0430\u0441\u0442\u0438", "es": "Define las partes del gobierno"}, "Protects the rights of the people": {"ru": "\u0417\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439", "es": "Protege los derechos de las personas"}, "You only need to give ONE answer during your citizenship interview.": {"ru": "\u041d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u041e\u0414\u0418\u041d \u043e\u0442\u0432\u0435\u0442.", "es": "Solo necesita dar UNA respuesta durante su entrevista de ciudadan\u00eda."}, "Memory Connection": {"ru": "\u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u0434\u043b\u044f \u0437\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u044f", "es": "Conexi\u00f3n para recordar"}, "Constitute \u2192 Constitution": {"ru": "Constitute (\u00ab\u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0442\u044c\u00bb) \u2192 Constitution (\u00ab\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f\u00bb)", "es": "Constitute (\u00abconstituir\u00bb) \u2192 Constitution (\u00abConstituci\u00f3n\u00bb)"}, "The verb constitute means to form or to make up.": {"ru": "\u0413\u043b\u0430\u0433\u043e\u043b constitute \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u00ab\u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c\u00bb, \u00ab\u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0442\u044c\u00bb \u0438\u043b\u0438 \u00ab\u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c\u00bb.", "es": "El verbo constitute significa \u00abformar\u00bb o \u00abcomponer\u00bb."}, "The Constitution forms the government.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0432\u043b\u0430\u0441\u0442\u0438.", "es": "La Constituci\u00f3n establece el gobierno."}, "Remember this connection, and you already know one correct interview answer!": {"ru": "\u0417\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u0435 \u044d\u0442\u0443 \u0441\u0432\u044f\u0437\u044c \u2014 \u0438 \u0432\u044b \u0443\u0436\u0435 \u0437\u043d\u0430\u0435\u0442\u0435 \u043e\u0434\u0438\u043d \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0434\u043b\u044f \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f!", "es": "\u00a1Recuerde esta conexi\u00f3n y ya sabr\u00e1 una respuesta correcta para la entrevista!"}, "Form": {"ru": "\u0421\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c, \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0442\u044c", "es": "Formar"}, "Define": {"ru": "\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0442\u044c", "es": "Definir"}, "Power": {"ru": "\u041f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u0435", "es": "Poder"}, "Branch of government": {"ru": "\u0412\u0435\u0442\u0432\u044c \u0432\u043b\u0430\u0441\u0442\u0438", "es": "Rama del gobierno"}, "Right": {"ru": "\u041f\u0440\u0430\u0432\u043e", "es": "Derecho"}, "Protect": {"ru": "\u0417\u0430\u0449\u0438\u0449\u0430\u0442\u044c", "es": "Proteger"}, "To create or establish something.": {"ru": "\u0421\u043e\u0437\u0434\u0430\u0442\u044c \u0438\u043b\u0438 \u0443\u0447\u0440\u0435\u0434\u0438\u0442\u044c \u0447\u0442\u043e-\u043b\u0438\u0431\u043e.", "es": "Crear o establecer algo."}, "To explain clearly what something is or what it can do.": {"ru": "\u042f\u0441\u043d\u043e \u043e\u0431\u044a\u044f\u0441\u043d\u0438\u0442\u044c, \u0447\u0442\u043e \u0441\u043e\u0431\u043e\u0439 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0447\u0442\u043e-\u043b\u0438\u0431\u043e \u0438\u043b\u0438 \u0447\u0442\u043e \u043e\u043d\u043e \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u043b\u0430\u0442\u044c.", "es": "Explicar claramente qu\u00e9 es algo o qu\u00e9 puede hacer."}, "The authority to make decisions or take action.": {"ru": "\u041f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438\u043b\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c.", "es": "La autoridad para tomar decisiones o actuar."}, "One of the main parts of government, with its own responsibilities.": {"ru": "\u041e\u0434\u043d\u0430 \u0438\u0437 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0445 \u0447\u0430\u0441\u0442\u0435\u0439 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0432\u043b\u0430\u0441\u0442\u0438 \u0441\u043e \u0441\u0432\u043e\u0438\u043c\u0438 \u043e\u0431\u044f\u0437\u0430\u043d\u043d\u043e\u0441\u0442\u044f\u043c\u0438.", "es": "Una de las partes principales del gobierno, con sus propias responsabilidades."}, "A freedom or protection that people have under the law.": {"ru": "\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0438\u043b\u0438 \u0437\u0430\u0449\u0438\u0442\u0430, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0437\u0430\u043a\u043e\u043d \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043b\u044e\u0434\u044f\u043c.", "es": "Una libertad o protecci\u00f3n que las personas tienen conforme a la ley."}, "To keep someone or something safe from harm or unfair treatment.": {"ru": "\u041e\u0431\u0435\u0440\u0435\u0433\u0430\u0442\u044c \u043a\u043e\u0433\u043e-\u043b\u0438\u0431\u043e \u0438\u043b\u0438 \u0447\u0442\u043e-\u043b\u0438\u0431\u043e \u043e\u0442 \u0432\u0440\u0435\u0434\u0430 \u0438\u043b\u0438 \u043d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e\u0433\u043e \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f.", "es": "Mantener a alguien o algo a salvo de da\u00f1os o de un trato injusto."}, "Constitute \u2192 To form": {"ru": "Constitute \u2192 \u0421\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c", "es": "Constitute \u2192 Formar"}, "One government \u00b7 Three branches": {"ru": "\u041e\u0434\u043d\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0432\u043b\u0430\u0441\u0442\u0438 \u00b7 \u0422\u0440\u0438 \u0432\u0435\u0442\u0432\u0438", "es": "Un gobierno \u00b7 Tres ramas"}, "Each branch has authority": {"ru": "\u0423 \u043a\u0430\u0436\u0434\u043e\u0439 \u0432\u0435\u0442\u0432\u0438 \u0435\u0441\u0442\u044c \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f", "es": "Cada rama tiene autoridad"}, "Our constitutional rights": {"ru": "\u041d\u0430\u0448\u0438 \u043a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430", "es": "Nuestros derechos constitucionales"}, "Remember ONE answer.": {"ru": "\u0417\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u0435 \u041e\u0414\u0418\u041d \u043e\u0442\u0432\u0435\u0442.", "es": "Recuerde UNA respuesta."}, "Legislative": {"ru": "\u0417\u0430\u043a\u043e\u043d\u043e\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f", "es": "Legislativa"}, "Executive": {"ru": "\u0418\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f", "es": "Ejecutiva"}, "Judicial": {"ru": "\u0421\u0443\u0434\u0435\u0431\u043d\u0430\u044f", "es": "Judicial"}, "Makes laws": {"ru": "\u041f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0437\u0430\u043a\u043e\u043d\u044b", "es": "Elabora leyes"}, "Carries out laws": {"ru": "\u0418\u0441\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u0437\u0430\u043a\u043e\u043d\u044b", "es": "Ejecuta las leyes"}, "Interprets laws": {"ru": "\u0422\u043e\u043b\u043a\u0443\u0435\u0442 \u0437\u0430\u043a\u043e\u043d\u044b", "es": "Interpreta las leyes"}, "Examples of branch functions": {"ru": "\u041f\u0440\u0438\u043c\u0435\u0440\u044b \u0444\u0443\u043d\u043a\u0446\u0438\u0439 \u0432\u0435\u0442\u0432\u0435\u0439 \u0432\u043b\u0430\u0441\u0442\u0438", "es": "Ejemplos de funciones de las ramas del gobierno"}, "Freedom of speech \u00b7 Peaceful assembly": {"ru": "\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0441\u043b\u043e\u0432\u0430 \u00b7 \u041c\u0438\u0440\u043d\u044b\u0435 \u0441\u043e\u0431\u0440\u0430\u043d\u0438\u044f", "es": "Libertad de expresi\u00f3n \u00b7 Reuni\u00f3n pac\u00edfica"}, "Freedom of religion": {"ru": "\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f", "es": "Libertad de religi\u00f3n"}, "The United States has many laws. Laws are rules that people must follow.": {"ru": "\u0412 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445 \u043c\u043d\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u043e\u0432. \u0417\u0430\u043a\u043e\u043d\u044b \u2014 \u044d\u0442\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u043b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c.", "es": "Estados Unidos tiene muchas leyes. Las leyes son normas que las personas deben cumplir."}, "But one law is more important than all the others. It is the U.S. Constitution.": {"ru": "\u041d\u043e \u043e\u0434\u0438\u043d \u0437\u0430\u043a\u043e\u043d \u0432\u0430\u0436\u043d\u0435\u0435 \u0432\u0441\u0435\u0445 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445. \u042d\u0442\u043e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410.", "es": "Pero una ley es m\u00e1s importante que todas las dem\u00e1s. Es la Constituci\u00f3n de Estados Unidos."}, "The Constitution is the supreme law of the land. This means that other laws cannot go against it.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u2014 \u0432\u044b\u0441\u0448\u0438\u0439 \u0437\u0430\u043a\u043e\u043d \u0441\u0442\u0440\u0430\u043d\u044b. \u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0434\u0440\u0443\u0433\u0438\u0435 \u0437\u0430\u043a\u043e\u043d\u044b \u043d\u0435 \u043c\u043e\u0433\u0443\u0442 \u0435\u0439 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0438\u0442\u044c.", "es": "La Constituci\u00f3n es la ley suprema del pa\u00eds. Esto significa que las dem\u00e1s leyes no pueden contradecirla."}, "Some people answer this question with the Bill of Rights or the Declaration of Independence. These are important documents, but they are not the correct answer to this question. The Bill of Rights is part of the Constitution. The correct answer is the U.S. Constitution.": {"ru": "\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0442 \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441: \u00ab\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445\u00bb \u0438\u043b\u0438 \u00ab\u0414\u0435\u043a\u043b\u0430\u0440\u0430\u0446\u0438\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438\u00bb. \u042d\u0442\u043e \u0432\u0430\u0436\u043d\u044b\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b, \u043d\u043e \u043e\u043d\u0438 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u043c \u043e\u0442\u0432\u0435\u0442\u043e\u043c \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441. \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u2014 \u0447\u0430\u0441\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438. \u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u2014 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410.", "es": "Algunas personas responden a esta pregunta con \u00abla Carta de Derechos\u00bb o \u00abla Declaraci\u00f3n de Independencia\u00bb. Son documentos importantes, pero no son la respuesta correcta a esta pregunta. La Carta de Derechos forma parte de la Constituci\u00f3n. La respuesta correcta es la Constituci\u00f3n de Estados Unidos."}, "If the officer asks, \u2018What is the supreme law of the land?\u2019 you can answer, \u2018The Constitution.\u2019": {"ru": "\u0415\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u041a\u0430\u043a\u043e\u0432 \u0432\u044b\u0441\u0448\u0438\u0439 \u0437\u0430\u043a\u043e\u043d \u0441\u0442\u0440\u0430\u043d\u044b?\u00bb, \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abThe Constitution\u00bb.", "es": "Si el funcionario pregunta: \u00ab\u00bfCu\u00e1l es la ley suprema del pa\u00eds?\u00bb, puede responder: \u00abThe Constitution\u00bb."}, "The word \u2018constitute\u2019 means \u2018to form\u2019 or \u2018to make up.\u2019 This can help you remember one important job of the Constitution: it forms the government.": {"ru": "\u0421\u043b\u043e\u0432\u043e constitute \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u00ab\u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c\u00bb \u0438\u043b\u0438 \u00ab\u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c\u00bb. \u042d\u0442\u043e \u043f\u043e\u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u044c \u043e\u0434\u043d\u0443 \u0432\u0430\u0436\u043d\u0443\u044e \u0444\u0443\u043d\u043a\u0446\u0438\u044e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438: \u043e\u043d\u0430 \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0432\u043b\u0430\u0441\u0442\u0438.", "es": "La palabra constitute significa \u00abformar\u00bb o \u00abcomponer\u00bb. Esto puede ayudarle a recordar una funci\u00f3n importante de la Constituci\u00f3n: establece el gobierno."}, "The Constitution establishes the U.S. government. It also defines its three branches: legislative, executive, and judicial.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0432\u043b\u0430\u0441\u0442\u0438 \u0421\u0428\u0410. \u041e\u043d\u0430 \u0442\u0430\u043a\u0436\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u0442\u0440\u0438 \u0432\u0435\u0442\u0432\u0438 \u0432\u043b\u0430\u0441\u0442\u0438: \u0437\u0430\u043a\u043e\u043d\u043e\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u0443\u044e, \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0438 \u0441\u0443\u0434\u0435\u0431\u043d\u0443\u044e.", "es": "La Constituci\u00f3n establece el gobierno de Estados Unidos. Tambi\u00e9n define sus tres ramas: legislativa, ejecutiva y judicial."}, "The Constitution explains what the government and its different branches have the authority to do.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0435\u0442, \u043a\u0430\u043a\u0438\u0435 \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f \u0438\u043c\u0435\u044e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0438 \u0435\u0433\u043e \u0440\u0430\u0437\u043b\u0438\u0447\u043d\u044b\u0435 \u0432\u0435\u0442\u0432\u0438.", "es": "La Constituci\u00f3n explica qu\u00e9 facultades tienen el gobierno y sus distintos poderes."}, "The Constitution also protects people's rights, such as freedom of speech and freedom of religion.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0441\u043b\u043e\u0432\u0430 \u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f.", "es": "La Constituci\u00f3n tambi\u00e9n protege los derechos de las personas, como la libertad de expresi\u00f3n y la libertad de religi\u00f3n."}, "The Constitution forms the government, defines its parts and powers, and protects people's rights. At your citizenship interview, you only need to name one of these things.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0432\u043b\u0430\u0441\u0442\u0438, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u0438\u0445 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0438 \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f \u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439. \u041d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043d\u0430\u0437\u0432\u0430\u0442\u044c \u043e\u0434\u043d\u0443 \u0438\u0437 \u044d\u0442\u0438\u0445 \u0444\u0443\u043d\u043a\u0446\u0438\u0439.", "es": "La Constituci\u00f3n establece el gobierno, define sus partes y poderes, y protege los derechos de las personas. En la entrevista de ciudadan\u00eda, solo necesita mencionar una de estas funciones."}, "To show your choice in an election or decision.": {"ru": "\u0412\u044b\u0440\u0430\u0437\u0438\u0442\u044c \u0441\u0432\u043e\u0439 \u0432\u044b\u0431\u043e\u0440 \u043d\u0430 \u0432\u044b\u0431\u043e\u0440\u0430\u0445 \u0438\u043b\u0438 \u043f\u0440\u0438 \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.", "es": "Expresar su elecci\u00f3n en una elecci\u00f3n o decisi\u00f3n."}, "A person people choose to speak and make government decisions for them.": {"ru": "\u0427\u0435\u043b\u043e\u0432\u0435\u043a, \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043b\u044e\u0434\u0438 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u043e\u043d \u0432\u044b\u0441\u0442\u0443\u043f\u0430\u043b \u043e\u0442 \u0438\u0445 \u0438\u043c\u0435\u043d\u0438 \u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u043b \u0437\u0430 \u043d\u0438\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.", "es": "Una persona que la gente elige para hablar y tomar decisiones de gobierno en su nombre."}, "A form of democracy in which people vote on laws and decisions themselves.": {"ru": "\u0424\u043e\u0440\u043c\u0430 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u0441\u0430\u043c\u0438 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442 \u043f\u043e \u0437\u0430\u043a\u043e\u043d\u0430\u043c \u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c.", "es": "Una forma de democracia en la que las personas votan ellas mismas sobre las leyes y las decisiones."}, "A form of democracy in which people choose representatives to make government decisions for them.": {"ru": "\u0424\u043e\u0440\u043c\u0430 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439, \u0447\u0442\u043e\u0431\u044b \u0442\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u043b\u0438 \u0437\u0430 \u043d\u0438\u0445 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.", "es": "Una forma de democracia en la que las personas eligen representantes para tomar decisiones de gobierno en su nombre."}, "A form of government in which people choose representatives. The country does not have a king or queen as its head of state.": {"ru": "\u0424\u043e\u0440\u043c\u0430 \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439. \u0412\u043e \u0433\u043b\u0430\u0432\u0435 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u043d\u0435 \u0441\u0442\u043e\u0438\u0442 \u043a\u043e\u0440\u043e\u043b\u044c \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430.", "es": "Una forma de gobierno en la que las personas eligen representantes. El pa\u00eds no tiene un rey ni una reina como jefe de Estado."}, "In a direct democracy, people make decisions by voting on them themselves. For example, everyone votes to decide whether to build a new playground in their park.": {"ru": "\u041f\u0440\u0438 \u043f\u0440\u044f\u043c\u043e\u0439 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438 \u043b\u044e\u0434\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f, \u0441\u0430\u043c\u0438 \u0433\u043e\u043b\u043e\u0441\u0443\u044f \u043f\u043e \u043d\u0438\u043c. \u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u0441\u0435 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u0440\u0435\u0448\u0438\u0442\u044c, \u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043b\u0438 \u043d\u043e\u0432\u0443\u044e \u0434\u0435\u0442\u0441\u043a\u0443\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0443 \u0432 \u0441\u0432\u043e\u0451\u043c \u043f\u0430\u0440\u043a\u0435.", "es": "En una democracia directa, las personas toman decisiones votando sobre ellas mismas. Por ejemplo, todos votan para decidir si se construye un nuevo parque infantil en su parque."}, "In a representative democracy, people choose representatives by voting. The representatives make many decisions for the people.": {"ru": "\u041f\u0440\u0438 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438 \u043b\u044e\u0434\u0438 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u043f\u0443\u0442\u0451\u043c \u0433\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u043d\u0438\u044f. \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u043c\u043d\u043e\u0433\u0438\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0437\u0430 \u043b\u044e\u0434\u0435\u0439.", "es": "En una democracia representativa, las personas eligen representantes mediante el voto. Los representantes toman muchas decisiones en nombre de la gente."}, "The United States is a representative democracy. Americans elect representatives who make laws for the country.": {"ru": "\u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u2014 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f. \u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u044b \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0437\u0430\u043a\u043e\u043d\u044b \u0434\u043b\u044f \u0441\u0442\u0440\u0430\u043d\u044b.", "es": "Estados Unidos es una democracia representativa. Los estadounidenses eligen representantes que hacen las leyes del pa\u00eds."}, "Stage 1": {"ru": "\u042d\u0442\u0430\u043f 1", "es": "Etapa 1"}, "Stage 2": {"ru": "\u042d\u0442\u0430\u043f 2", "es": "Etapa 2"}, "Stage 3": {"ru": "\u042d\u0442\u0430\u043f 3", "es": "Etapa 3"}, "The highest law in the country. No other law can go against it.": {"ru": "\u0412\u044b\u0441\u0448\u0438\u0439 \u0437\u0430\u043a\u043e\u043d \u0441\u0442\u0440\u0430\u043d\u044b. \u041d\u0438 \u043e\u0434\u0438\u043d \u0434\u0440\u0443\u0433\u043e\u0439 \u0437\u0430\u043a\u043e\u043d \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0435\u043c\u0443 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0438\u0442\u044c.", "es": "La ley suprema del pa\u00eds. Ninguna otra ley puede contradecirla."}, "The U.S. Constitution starts with the words \u201cWe the People.\u201d What does \u201cWe the People\u201d mean?": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb. \u0427\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb?", "es": "La Constituci\u00f3n de Estados Unidos comienza con las palabras \u00abNosotros, el Pueblo\u00bb. \u00bfQu\u00e9 significa \u00abNosotros, el Pueblo\u00bb?"}, "Self-government": {"ru": "\u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435", "es": "Autogobierno"}, "Popular sovereignty": {"ru": "\u041d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u0438\u0442\u0435\u0442", "es": "Soberan\u00eda popular"}, "Consent of the governed": {"ru": "\u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0445", "es": "Consentimiento de los gobernados"}, "People should govern themselves": {"ru": "\u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438", "es": "Las personas deben gobernarse a s\u00ed mismas"}, "Social contract": {"ru": "\u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440", "es": "Contrato social"}, "Official Question": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441", "es": "Pregunta oficial"}, "Understanding the Question: Constitution": {"ru": "\u041f\u043e\u043d\u0438\u043c\u0430\u0435\u043c \u0432\u043e\u043f\u0440\u043e\u0441: \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f", "es": "Comprender la pregunta: la Constituci\u00f3n"}, "This question checks if you understand an important idea about American government.": {"ru": "\u042d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442, \u043f\u043e\u043d\u0438\u043c\u0430\u0435\u0442\u0435 \u043b\u0438 \u0432\u044b \u0432\u0430\u0436\u043d\u044b\u0439 \u043f\u0440\u0438\u043d\u0446\u0438\u043f \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f.", "es": "Esta pregunta comprueba si comprende una idea importante sobre el gobierno estadounidense."}, "The U.S. Constitution begins with \u2018We the People,\u2019 not \u2018We the President,\u2019 \u2018We the King,\u2019 or \u2018We the Government.\u2019": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb, \u0430 \u043d\u0435 \u00ab\u041c\u044b, \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u00bb, \u00ab\u041c\u044b, \u043a\u043e\u0440\u043e\u043b\u044c\u00bb \u0438\u043b\u0438 \u00ab\u041c\u044b, \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u00bb.", "es": "La Constituci\u00f3n de Estados Unidos comienza con \u00abNosotros, el Pueblo\u00bb, no con \u00abNosotros, el Presidente\u00bb, \u00abNosotros, el Rey\u00bb ni \u00abNosotros, el Gobierno\u00bb."}, "Why?": {"ru": "\u041f\u043e\u0447\u0435\u043c\u0443?", "es": "\u00bfPor qu\u00e9?"}, "Political Power Comes from the People": {"ru": "\u041f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u043b\u0430\u0441\u0442\u044c \u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u043e\u0442 \u043d\u0430\u0440\u043e\u0434\u0430", "es": "El poder pol\u00edtico proviene del pueblo"}, "Because in the United States, political power belongs to the people, not to one leader or the government itself.": {"ru": "\u041f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445 \u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u043b\u0430\u0441\u0442\u044c \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043d\u0430\u0440\u043e\u0434\u0443, \u0430 \u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044e \u0438\u043b\u0438 \u0441\u0430\u043c\u043e\u043c\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443.", "es": "Porque en Estados Unidos el poder pol\u00edtico pertenece al pueblo, no a un solo l\u00edder ni al propio gobierno."}, "The people give the government the power to make decisions and laws for them.": {"ru": "\u041b\u044e\u0434\u0438 \u043d\u0430\u0434\u0435\u043b\u044f\u044e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f\u043c\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0437\u0430 \u043d\u0438\u0445 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u043a\u043e\u043d\u044b.", "es": "El pueblo da al gobierno el poder de tomar decisiones y hacer leyes en su nombre."}, "Understanding the Accepted Answers": {"ru": "\u041f\u043e\u043d\u0438\u043c\u0430\u0435\u043c \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0435 \u043e\u0442\u0432\u0435\u0442\u044b", "es": "Comprender las respuestas aceptadas"}, "There are five accepted answers to this question.": {"ru": "\u041d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u0435\u0441\u0442\u044c \u043f\u044f\u0442\u044c \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432.", "es": "Hay cinco respuestas aceptadas para esta pregunta."}, "They use different words, but they all express the same main idea: the power of government comes from the people.": {"ru": "\u0412 \u043d\u0438\u0445 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0440\u0430\u0437\u043d\u044b\u0435 \u0441\u043b\u043e\u0432\u0430, \u043d\u043e \u0432\u0441\u0435 \u043e\u043d\u0438 \u0432\u044b\u0440\u0430\u0436\u0430\u044e\u0442 \u043e\u0434\u043d\u0443 \u0433\u043b\u0430\u0432\u043d\u0443\u044e \u043c\u044b\u0441\u043b\u044c: \u0432\u043b\u0430\u0441\u0442\u044c \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u043e\u0442 \u043d\u0430\u0440\u043e\u0434\u0430.", "es": "Usan palabras diferentes, pero todas expresan la misma idea principal: el poder del gobierno proviene del pueblo."}, "Let's take a closer look at each answer.": {"ru": "\u0414\u0430\u0432\u0430\u0439\u0442\u0435 \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0438\u043c \u043a\u0430\u0436\u0434\u044b\u0439 \u043e\u0442\u0432\u0435\u0442.", "es": "Veamos cada respuesta con m\u00e1s detalle."}, "Self-government / People Should Govern Themselves": {"ru": "\u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 / \u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438", "es": "Autogobierno / Las personas deben gobernarse a s\u00ed mismas"}, "Self-government means that people govern themselves, usually by choosing representatives to make decisions for them.": {"ru": "\u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442 \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438, \u043e\u0431\u044b\u0447\u043d\u043e \u0432\u044b\u0431\u0438\u0440\u0430\u044f \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e\u0442 \u0438\u0445 \u0438\u043c\u0435\u043d\u0438.", "es": "El autogobierno significa que las personas se gobiernan a s\u00ed mismas, normalmente eligiendo representantes que toman decisiones en su nombre."}, "\u2018People should govern themselves\u2019 expresses the same idea.": {"ru": "\u00ab\u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438\u00bb \u0432\u044b\u0440\u0430\u0436\u0430\u0435\u0442 \u0442\u0443 \u0436\u0435 \u043c\u044b\u0441\u043b\u044c.", "es": "\u00abLas personas deben gobernarse a s\u00ed mismas\u00bb expresa la misma idea."}, "Popular Sovereignty": {"ru": "\u041d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u0438\u0442\u0435\u0442", "es": "Soberan\u00eda popular"}, "Popular sovereignty means that the people have the power to govern their country, not one leader or ruler.": {"ru": "\u041d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u0438\u0442\u0435\u0442 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0432\u043b\u0430\u0441\u0442\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u0442\u0440\u0430\u043d\u043e\u0439 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043d\u0430\u0440\u043e\u0434\u0443, \u0430 \u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044e \u0438\u043b\u0438 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044e.", "es": "La soberan\u00eda popular significa que el pueblo tiene el poder de gobernar su pa\u00eds, no un solo l\u00edder o gobernante."}, "Consent of the Governed": {"ru": "\u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0445", "es": "Consentimiento de los gobernados"}, "Consent of the governed means that people agree to let their government make decisions for them.": {"ru": "\u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0445 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u043b\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e\u0442 \u0438\u0445 \u0438\u043c\u0435\u043d\u0438.", "es": "El consentimiento de los gobernados significa que las personas aceptan que su gobierno tome decisiones en su nombre."}, "Social Contract": {"ru": "\u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440", "es": "Contrato social"}, "A social contract is an agreement in which people create a government and agree to follow certain rules.": {"ru": "\u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440 \u2014 \u044d\u0442\u043e \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043b\u044e\u0434\u0438 \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u044e\u0442\u0441\u044f \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0442\u044c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.", "es": "Un contrato social es un acuerdo por el que las personas crean un gobierno y aceptan seguir ciertas reglas."}, "In return, the government protects their rights and helps society function well.": {"ru": "\u0412\u0437\u0430\u043c\u0435\u043d \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0438\u0445 \u043f\u0440\u0430\u0432\u0430 \u0438 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0443 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c.", "es": "A cambio, el gobierno protege sus derechos y ayuda a que la sociedad funcione bien."}, "Common Interview Mistake": {"ru": "\u0422\u0438\u043f\u0438\u0447\u043d\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430 \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438", "es": "Error com\u00fan en la entrevista"}, "Some people, when answering this question, repeat the words \u2018We the People\u2019 or start saying more words from the Constitution.": {"ru": "\u041e\u0442\u0432\u0435\u0447\u0430\u044f \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441, \u043d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043b\u044e\u0434\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb \u0438\u043b\u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u044e\u0442 \u0446\u0438\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u043b\u043e\u0432\u0430 \u0438\u0437 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "Al responder a esta pregunta, algunas personas repiten las palabras \u00abNosotros, el Pueblo\u00bb o empiezan a recitar m\u00e1s palabras de la Constituci\u00f3n."}, "But the officer is not asking you to repeat the Constitution. The officer wants to know what \u2018We the People\u2019 means.": {"ru": "\u041d\u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0441 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e. \u041e\u043d \u0445\u043e\u0447\u0435\u0442 \u0443\u0437\u043d\u0430\u0442\u044c, \u0447\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb.", "es": "Pero el funcionario no le pide que repita la Constituci\u00f3n. Quiere saber qu\u00e9 significa \u00abNosotros, el Pueblo\u00bb."}, "You can simply answer, \u2018Self-government.\u2019": {"ru": "\u041c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abSelf-government\u00bb.", "es": "Puede responder simplemente: \u00abSelf-government\u00bb."}, "Official Question and Accepted Answers": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0435 \u043e\u0442\u0432\u0435\u0442\u044b", "es": "Pregunta oficial y respuestas aceptadas"}, "So, if the officer asks you, \u2018The U.S. Constitution starts with the words \u201cWe the People.\u201d What does \u201cWe the People\u201d mean?\u2019": {"ru": "\u0418\u0442\u0430\u043a, \u0435\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u201e\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u201c. \u0427\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u201e\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u201c?\u00bb", "es": "Por tanto, si el funcionario le pregunta: \u00abLa Constituci\u00f3n de Estados Unidos comienza con las palabras \u201cNosotros, el Pueblo\u201d. \u00bfQu\u00e9 significa \u201cNosotros, el Pueblo\u201d?\u00bb"}, "You only need to give one accepted answer:": {"ru": "\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0439 \u043e\u0442\u0432\u0435\u0442:", "es": "Solo necesita dar una respuesta aceptada:"}, "Self-government.": {"ru": "\u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435.", "es": "Autogobierno."}, "Popular sovereignty.": {"ru": "\u041d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u0438\u0442\u0435\u0442.", "es": "Soberan\u00eda popular."}, "Consent of the governed.": {"ru": "\u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0445.", "es": "Consentimiento de los gobernados."}, "People should govern themselves.": {"ru": "\u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438.", "es": "Las personas deben gobernarse a s\u00ed mismas."}, "Social contract.": {"ru": "\u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440.", "es": "Contrato social."}, "1. Self-government": {"ru": "1. \u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435", "es": "1. Autogobierno"}, "2. Popular sovereignty": {"ru": "2. \u041d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u0438\u0442\u0435\u0442", "es": "2. Soberan\u00eda popular"}, "3. Consent of the governed": {"ru": "3. \u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0445", "es": "3. Consentimiento de los gobernados"}, "4. People should govern themselves": {"ru": "4. \u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438", "es": "4. Las personas deben gobernarse a s\u00ed mismas"}, "5. Social contract": {"ru": "5. \u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440", "es": "5. Contrato social"}, "Govern": {"ru": "\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c", "es": "Gobernar"}, "To lead or control a country or group of people.": {"ru": "\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u0442\u0440\u0430\u043d\u043e\u0439 \u0438\u043b\u0438 \u0433\u0440\u0443\u043f\u043f\u043e\u0439 \u043b\u044e\u0434\u0435\u0439.", "es": "Dirigir o controlar un pa\u00eds o un grupo de personas."}, "Government": {"ru": "\u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e", "es": "Gobierno"}, "The people and institutions that make decisions and laws for a country.": {"ru": "\u041b\u044e\u0434\u0438 \u0438 \u0443\u0447\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u043a\u043e\u043d\u044b \u0434\u043b\u044f \u0441\u0442\u0440\u0430\u043d\u044b.", "es": "Las personas e instituciones que toman decisiones y hacen leyes para un pa\u00eds."}, "Governed": {"ru": "\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0435", "es": "Gobernados"}, "People who are ruled or led by a government.": {"ru": "\u041b\u044e\u0434\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e.", "es": "Personas que est\u00e1n bajo la autoridad o direcci\u00f3n de un gobierno."}, "Consent": {"ru": "\u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435", "es": "Consentimiento"}, "Permission or agreement.": {"ru": "\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0438\u043b\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435.", "es": "Permiso o acuerdo."}, "People agree to let their government make decisions for them.": {"ru": "\u041b\u044e\u0434\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u043b\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e\u0442 \u0438\u0445 \u0438\u043c\u0435\u043d\u0438.", "es": "Las personas aceptan que su gobierno tome decisiones en su nombre."}, "The idea that the people have the power to govern their country, not one leader or ruler.": {"ru": "\u0418\u0434\u0435\u044f \u043e \u0442\u043e\u043c, \u0447\u0442\u043e \u0432\u043b\u0430\u0441\u0442\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u0442\u0440\u0430\u043d\u043e\u0439 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043d\u0430\u0440\u043e\u0434\u0443, \u0430 \u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044e \u0438\u043b\u0438 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044e.", "es": "La idea de que el pueblo tiene el poder de gobernar su pa\u00eds, no un solo l\u00edder o gobernante."}, "A system in which people govern themselves, directly or through representatives.": {"ru": "\u0421\u0438\u0441\u0442\u0435\u043c\u0430, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u043b\u044e\u0434\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442 \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438, \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0438\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439.", "es": "Un sistema en el que las personas se gobiernan a s\u00ed mismas, directamente o mediante representantes."}, "An agreement in which people create a government and agree to follow certain rules. In return, the government protects their rights and helps society function well.": {"ru": "\u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043b\u044e\u0434\u0438 \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u044e\u0442\u0441\u044f \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0442\u044c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430. \u0412\u0437\u0430\u043c\u0435\u043d \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0438\u0445 \u043f\u0440\u0430\u0432\u0430 \u0438 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0443 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c.", "es": "Un acuerdo por el que las personas crean un gobierno y aceptan seguir ciertas reglas. A cambio, el gobierno protege sus derechos y ayuda a que la sociedad funcione bien."}, "Key Takeaway": {"ru": "\u0413\u043b\u0430\u0432\u043d\u0430\u044f \u043c\u044b\u0441\u043b\u044c", "es": "Idea clave"}, "Explain what \u201cWe the People\u201d means.": {"ru": "\u041e\u0431\u044a\u044f\u0441\u043d\u0438\u0442\u0435, \u0447\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb.", "es": "Explique qu\u00e9 significa \u00abNosotros, el Pueblo\u00bb."}, "This question checks if you understand an important idea about American government.\n\nThe U.S. Constitution begins with \u2018We the People,\u2019 not \u2018We the President,\u2019 \u2018We the King,\u2019 or \u2018We the Government.\u2019\n\nWhy?": {"ru": "\u042d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442, \u043f\u043e\u043d\u0438\u043c\u0430\u0435\u0442\u0435 \u043b\u0438 \u0432\u044b \u0432\u0430\u0436\u043d\u044b\u0439 \u043f\u0440\u0438\u043d\u0446\u0438\u043f \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f.\n\n\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb, \u0430 \u043d\u0435 \u00ab\u041c\u044b, \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u00bb, \u00ab\u041c\u044b, \u043a\u043e\u0440\u043e\u043b\u044c\u00bb \u0438\u043b\u0438 \u00ab\u041c\u044b, \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u00bb.\n\n\u041f\u043e\u0447\u0435\u043c\u0443?", "es": "Esta pregunta comprueba si comprende una idea importante sobre el gobierno estadounidense.\n\nLa Constituci\u00f3n de Estados Unidos comienza con \u00abNosotros, el Pueblo\u00bb, no con \u00abNosotros, el Presidente\u00bb, \u00abNosotros, el Rey\u00bb ni \u00abNosotros, el Gobierno\u00bb.\n\n\u00bfPor qu\u00e9?"}, "Because in the United States, political power belongs to the people, not to one leader or the government itself.\n\nThe people give the government the power to make decisions and laws for them.": {"ru": "\u041f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445 \u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u043b\u0430\u0441\u0442\u044c \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043d\u0430\u0440\u043e\u0434\u0443, \u0430 \u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044e \u0438\u043b\u0438 \u0441\u0430\u043c\u043e\u043c\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443.\n\n\u041b\u044e\u0434\u0438 \u043d\u0430\u0434\u0435\u043b\u044f\u044e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f\u043c\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0437\u0430 \u043d\u0438\u0445 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u043a\u043e\u043d\u044b.", "es": "Porque en Estados Unidos el poder pol\u00edtico pertenece al pueblo, no a un solo l\u00edder ni al propio gobierno.\n\nEl pueblo da al gobierno el poder de tomar decisiones y hacer leyes en su nombre."}, "There are five accepted answers to this question.\n\nThey use different words, but they all express the same main idea: the power of government comes from the people.\n\nLet's take a closer look at each answer.": {"ru": "\u041d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u0435\u0441\u0442\u044c \u043f\u044f\u0442\u044c \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432.\n\n\u0412 \u043d\u0438\u0445 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0440\u0430\u0437\u043d\u044b\u0435 \u0441\u043b\u043e\u0432\u0430, \u043d\u043e \u0432\u0441\u0435 \u043e\u043d\u0438 \u0432\u044b\u0440\u0430\u0436\u0430\u044e\u0442 \u043e\u0434\u043d\u0443 \u0433\u043b\u0430\u0432\u043d\u0443\u044e \u043c\u044b\u0441\u043b\u044c: \u0432\u043b\u0430\u0441\u0442\u044c \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u043e\u0442 \u043d\u0430\u0440\u043e\u0434\u0430.\n\n\u0414\u0430\u0432\u0430\u0439\u0442\u0435 \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0438\u043c \u043a\u0430\u0436\u0434\u044b\u0439 \u043e\u0442\u0432\u0435\u0442.", "es": "Hay cinco respuestas aceptadas para esta pregunta.\n\nUsan palabras diferentes, pero todas expresan la misma idea principal: el poder del gobierno proviene del pueblo.\n\nVeamos cada respuesta con m\u00e1s detalle."}, "Self-government means that people govern themselves, usually by choosing representatives to make decisions for them.\n\n\u2018People should govern themselves\u2019 expresses the same idea.": {"ru": "\u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442 \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438, \u043e\u0431\u044b\u0447\u043d\u043e \u0432\u044b\u0431\u0438\u0440\u0430\u044f \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043e\u0442 \u0438\u0445 \u0438\u043c\u0435\u043d\u0438.\n\n\u00ab\u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438\u00bb \u0432\u044b\u0440\u0430\u0436\u0430\u0435\u0442 \u0442\u0443 \u0436\u0435 \u043c\u044b\u0441\u043b\u044c.", "es": "El autogobierno significa que las personas se gobiernan a s\u00ed mismas, normalmente eligiendo representantes que toman decisiones en su nombre.\n\n\u00abLas personas deben gobernarse a s\u00ed mismas\u00bb expresa la misma idea."}, "A social contract is an agreement in which people create a government and agree to follow certain rules.\n\nIn return, the government protects their rights and helps society function well.": {"ru": "\u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440 \u2014 \u044d\u0442\u043e \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043b\u044e\u0434\u0438 \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u044e\u0442\u0441\u044f \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0442\u044c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.\n\n\u0412\u0437\u0430\u043c\u0435\u043d \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0438\u0445 \u043f\u0440\u0430\u0432\u0430 \u0438 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0443 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c.", "es": "Un contrato social es un acuerdo por el que las personas crean un gobierno y aceptan seguir ciertas reglas.\n\nA cambio, el gobierno protege sus derechos y ayuda a que la sociedad funcione bien."}, "Some people, when answering this question, repeat the words \u2018We the People\u2019 or start saying more words from the Constitution.\n\nBut the officer is not asking you to repeat the Constitution. The officer wants to know what \u2018We the People\u2019 means.\n\nYou can simply answer, \u2018Self-government.\u2019": {"ru": "\u041e\u0442\u0432\u0435\u0447\u0430\u044f \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441, \u043d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043b\u044e\u0434\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb \u0438\u043b\u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u044e\u0442 \u0446\u0438\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u043b\u043e\u0432\u0430 \u0438\u0437 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.\n\n\u041d\u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0441 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e. \u041e\u043d \u0445\u043e\u0447\u0435\u0442 \u0443\u0437\u043d\u0430\u0442\u044c, \u0447\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb.\n\n\u041c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abSelf-government\u00bb.", "es": "Al responder a esta pregunta, algunas personas repiten las palabras \u00abNosotros, el Pueblo\u00bb o empiezan a recitar m\u00e1s palabras de la Constituci\u00f3n.\n\nPero el funcionario no le pide que repita la Constituci\u00f3n. Quiere saber qu\u00e9 significa \u00abNosotros, el Pueblo\u00bb.\n\nPuede responder simplemente: \u00abSelf-government\u00bb."}, "So, if the officer asks you, \u2018The U.S. Constitution starts with the words \u201cWe the People.\u201d What does \u201cWe the People\u201d mean?\u2019\n\nYou only need to give one accepted answer:\n\nSelf-government.\n\nPopular sovereignty.\n\nConsent of the governed.\n\nPeople should govern themselves.\n\nSocial contract.": {"ru": "\u0418\u0442\u0430\u043a, \u0435\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u201e\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u201c. \u0427\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 \u201e\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u201c?\u00bb\n\n\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0439 \u043e\u0442\u0432\u0435\u0442:\n\n\u0421\u0430\u043c\u043e\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435.\n\n\u041d\u0430\u0440\u043e\u0434\u043d\u044b\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u0438\u0442\u0435\u0442.\n\n\u0421\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0445.\n\n\u041b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0441\u043e\u0431\u043e\u0439 \u0441\u0430\u043c\u0438.\n\n\u041e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440.", "es": "Por tanto, si el funcionario le pregunta: \u00abLa Constituci\u00f3n de Estados Unidos comienza con las palabras \u201cNosotros, el Pueblo\u201d. \u00bfQu\u00e9 significa \u201cNosotros, el Pueblo\u201d?\u00bb\n\nSolo necesita dar una respuesta aceptada:\n\nAutogobierno.\n\nSoberan\u00eda popular.\n\nConsentimiento de los gobernados.\n\nLas personas deben gobernarse a s\u00ed mismas.\n\nContrato social."}, "Official USCIS Question #4": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 USCIS \u2116 4", "es": "Pregunta oficial de USCIS n.\u00ba 4"}, "Understanding the Question": {"ru": "\u041f\u043e\u043d\u0438\u043c\u0430\u0435\u043c \u0432\u043e\u043f\u0440\u043e\u0441", "es": "Comprender la pregunta"}, "\u201cWe the People\u201d means that political power belongs to the people, not to a ruler or the government itself.": {"ru": "\u00ab\u041c\u044b, \u043d\u0430\u0440\u043e\u0434\u00bb \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u043b\u0430\u0441\u0442\u044c \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043d\u0430\u0440\u043e\u0434\u0443, \u0430 \u043d\u0435 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044e \u0438\u043b\u0438 \u0441\u0430\u043c\u043e\u043c\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443.", "es": "\u00abNosotros, el Pueblo\u00bb significa que el poder pol\u00edtico pertenece al pueblo, no a un gobernante ni al propio gobierno."}, "How are changes made to the U.S. Constitution?": {"ru": "\u041a\u0430\u043a \u0432\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0421\u0428\u0410?", "es": "\u00bfC\u00f3mo se realizan cambios en la Constituci\u00f3n de Estados Unidos?"}, "Amendments": {"ru": "\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0438", "es": "Enmiendas"}, "The amendment process": {"ru": "\u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0432\u043d\u0435\u0441\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a", "es": "El proceso de enmienda"}, "Official USCIS Question #5": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 USCIS \u2116 5", "es": "Pregunta oficial de USCIS n.\u00ba 5"}, "The U.S. Constitution was written more than 200 years ago.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u0431\u044b\u043b\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0430 \u0431\u043e\u043b\u0435\u0435 200 \u043b\u0435\u0442 \u043d\u0430\u0437\u0430\u0434.", "es": "La Constituci\u00f3n de Estados Unidos fue escrita hace m\u00e1s de 200 a\u00f1os."}, "But the country has changed a lot since then.": {"ru": "\u041d\u043e \u0441 \u0442\u0435\u0445 \u043f\u043e\u0440 \u0441\u0442\u0440\u0430\u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0430\u0441\u044c.", "es": "Pero el pa\u00eds ha cambiado mucho desde entonces."}, "The Constitution can change too. But changing the Constitution is harder than making a new law.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0442\u043e\u0436\u0435 \u043c\u043e\u0436\u043d\u043e \u0438\u0437\u043c\u0435\u043d\u044f\u0442\u044c. \u041d\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0441\u043b\u043e\u0436\u043d\u0435\u0435, \u0447\u0435\u043c \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u043d\u043e\u0432\u044b\u0439 \u0437\u0430\u043a\u043e\u043d.", "es": "La Constituci\u00f3n tambi\u00e9n puede cambiar. Pero cambiar la Constituci\u00f3n es m\u00e1s dif\u00edcil que aprobar una nueva ley."}, "What Is an Amendment?": {"ru": "\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430?", "es": "\u00bfQu\u00e9 es una enmienda?"}, "An amendment is an official change or addition to the Constitution.": {"ru": "\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u2014 \u044d\u0442\u043e \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0438\u043b\u0438 \u0434\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "Una enmienda es un cambio o una adici\u00f3n oficial a la Constituci\u00f3n."}, "When an amendment is approved, it becomes part of the Constitution.": {"ru": "\u041f\u043e\u0441\u043b\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u0447\u0430\u0441\u0442\u044c\u044e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "Cuando se aprueba una enmienda, pasa a formar parte de la Constituci\u00f3n."}, "This means we can change the Constitution without writing a completely new one.": {"ru": "\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043c\u044b \u043c\u043e\u0436\u0435\u043c \u0438\u0437\u043c\u0435\u043d\u044f\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e, \u043d\u0435 \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043d\u043e\u0432\u0443\u044e.", "es": "Esto significa que podemos cambiar la Constituci\u00f3n sin escribir una completamente nueva."}, "The Amendment Process": {"ru": "\u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0432\u043d\u0435\u0441\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a", "es": "El proceso de enmienda"}, "There are special steps to change the Constitution.": {"ru": "\u0414\u043b\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u043f\u0440\u0435\u0434\u0443\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0430 \u043e\u0441\u043e\u0431\u0430\u044f \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430.", "es": "Existen pasos especiales para cambiar la Constituci\u00f3n."}, "First, a change must be suggested.": {"ru": "\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442\u044c \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435.", "es": "Primero, se debe proponer un cambio."}, "Then, 3/4 of the states must agree to the change.": {"ru": "\u0417\u0430\u0442\u0435\u043c \u0442\u0440\u0438 \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u0438 \u0448\u0442\u0430\u0442\u043e\u0432 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u0441\u044f \u0441 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435\u043c.", "es": "Despu\u00e9s, tres cuartas partes de los estados deben estar de acuerdo con el cambio."}, "This means many states must agree before the Constitution can change.": {"ru": "\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0434\u043b\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u043c\u043d\u043e\u0433\u0438\u0445 \u0448\u0442\u0430\u0442\u043e\u0432.", "es": "Esto significa que muchos estados deben estar de acuerdo antes de que pueda cambiarse la Constituci\u00f3n."}, "Connecting the Answers": {"ru": "\u0421\u0432\u044f\u0437\u044c \u043c\u0435\u0436\u0434\u0443 \u043e\u0442\u0432\u0435\u0442\u0430\u043c\u0438", "es": "La relaci\u00f3n entre las respuestas"}, "There are two accepted answers: 'Amendments' and 'The amendment process.'": {"ru": "\u0415\u0441\u0442\u044c \u0434\u0432\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u0430: \u00abAmendments\u00bb \u0438 \u00abThe amendment process\u00bb.", "es": "Hay dos respuestas aceptadas: \u00abAmendments\u00bb y \u00abThe amendment process\u00bb."}, "They mean the same thing.": {"ru": "\u041e\u043d\u0438 \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u043e\u0434\u043d\u043e \u0438 \u0442\u043e \u0436\u0435.", "es": "Significan lo mismo."}, "The question asks 'how,' but you do not need to explain all the steps during your citizenship interview.": {"ru": "\u0412\u043e\u043f\u0440\u043e\u0441 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043e \u0441\u043b\u043e\u0432\u0430 \u00ab\u043a\u0430\u043a\u00bb, \u043d\u043e \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u0434\u043b\u044f \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u0430 \u043d\u0435 \u043d\u0443\u0436\u043d\u043e \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0442\u044c \u0432\u0441\u0435 \u044d\u0442\u0430\u043f\u044b.", "es": "La pregunta dice \u00abc\u00f3mo\u00bb, pero no necesita explicar todos los pasos durante su entrevista de ciudadan\u00eda."}, "You only need to give one of the two accepted answers.": {"ru": "\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u0438\u0437 \u0434\u0432\u0443\u0445 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432.", "es": "Solo necesita dar una de las dos respuestas aceptadas."}, "Some people think the President can change the Constitution by signing a new law.": {"ru": "\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0434\u0443\u043c\u0430\u044e\u0442, \u0447\u0442\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u043c\u043e\u0436\u0435\u0442 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e, \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u0432 \u043d\u043e\u0432\u044b\u0439 \u0437\u0430\u043a\u043e\u043d.", "es": "Algunas personas creen que el presidente puede cambiar la Constituci\u00f3n firmando una nueva ley."}, "But changing the Constitution is different from making a new law.": {"ru": "\u041d\u043e \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u043e\u0442\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u0430.", "es": "Pero cambiar la Constituci\u00f3n es diferente de aprobar una nueva ley."}, "The President does not need to sign or approve amendments to the Constitution.": {"ru": "\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0443 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u0434\u043f\u0438\u0441\u044b\u0432\u0430\u0442\u044c \u0438\u043b\u0438 \u043e\u0434\u043e\u0431\u0440\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0438 \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "El presidente no necesita firmar ni aprobar las enmiendas a la Constituci\u00f3n."}, "If the officer asks how changes are made to the Constitution, you can simply answer, 'Amendments.'": {"ru": "\u0415\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442, \u043a\u0430\u043a \u0432\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e, \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abAmendments\u00bb.", "es": "Si el funcionario pregunta c\u00f3mo se realizan cambios en la Constituci\u00f3n, puede responder simplemente: \u00abAmendments\u00bb."}, "So, if the officer asks you, 'How are changes made to the U.S. Constitution?'": {"ru": "\u0418\u0442\u0430\u043a, \u0435\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u041a\u0430\u043a \u0432\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0421\u0428\u0410?\u00bb", "es": "Por tanto, si el funcionario le pregunta: \u00ab\u00bfC\u00f3mo se realizan cambios en la Constituci\u00f3n de Estados Unidos?\u00bb"}, "Amendments.": {"ru": "\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0438.", "es": "Enmiendas."}, "The amendment process.": {"ru": "\u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0432\u043d\u0435\u0441\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a.", "es": "El proceso de enmienda."}, "Amend": {"ru": "\u0412\u043d\u043e\u0441\u0438\u0442\u044c \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f", "es": "Enmendar"}, "To make a change to a law or official document.": {"ru": "\u0412\u043d\u0435\u0441\u0442\u0438 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0432 \u0437\u0430\u043a\u043e\u043d \u0438\u043b\u0438 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442.", "es": "Realizar un cambio en una ley o un documento oficial."}, "Amendment": {"ru": "\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0430", "es": "Enmienda"}, "An official change or addition to a law or document.": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0438\u043b\u0438 \u0434\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a \u0437\u0430\u043a\u043e\u043d\u0443 \u0438\u043b\u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0443.", "es": "Un cambio o una adici\u00f3n oficial a una ley o un documento."}, "Process": {"ru": "\u041f\u0440\u043e\u0446\u0435\u0441\u0441", "es": "Proceso"}, "A series of steps taken to do something.": {"ru": "\u041f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0434\u043b\u044f \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0439 \u0446\u0435\u043b\u0438.", "es": "Una serie de pasos que se siguen para hacer algo."}, "Amendment process": {"ru": "\u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0432\u043d\u0435\u0441\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a", "es": "Proceso de enmienda"}, "The steps used to officially change the Constitution.": {"ru": "\u042d\u0442\u0430\u043f\u044b, \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u0435 \u0434\u043b\u044f \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "Los pasos que se siguen para cambiar oficialmente la Constituci\u00f3n."}, "Amendment = an official change to the Constitution.": {"ru": "\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 = \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "Enmienda = un cambio oficial a la Constituci\u00f3n."}, "The U.S. Constitution was written more than 200 years ago.\n\nBut the country has changed a lot since then.\n\nThe Constitution can change too. But changing the Constitution is harder than making a new law.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410 \u0431\u044b\u043b\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0430 \u0431\u043e\u043b\u0435\u0435 200 \u043b\u0435\u0442 \u043d\u0430\u0437\u0430\u0434.\n\n\u041d\u043e \u0441 \u0442\u0435\u0445 \u043f\u043e\u0440 \u0441\u0442\u0440\u0430\u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0430\u0441\u044c.\n\n\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0442\u043e\u0436\u0435 \u043c\u043e\u0436\u043d\u043e \u0438\u0437\u043c\u0435\u043d\u044f\u0442\u044c. \u041d\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0441\u043b\u043e\u0436\u043d\u0435\u0435, \u0447\u0435\u043c \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u043d\u043e\u0432\u044b\u0439 \u0437\u0430\u043a\u043e\u043d.", "es": "La Constituci\u00f3n de Estados Unidos fue escrita hace m\u00e1s de 200 a\u00f1os.\n\nPero el pa\u00eds ha cambiado mucho desde entonces.\n\nLa Constituci\u00f3n tambi\u00e9n puede cambiar. Pero cambiar la Constituci\u00f3n es m\u00e1s dif\u00edcil que aprobar una nueva ley."}, "An amendment is an official change or addition to the Constitution.\n\nWhen an amendment is approved, it becomes part of the Constitution.\n\nThis means we can change the Constitution without writing a completely new one.": {"ru": "\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u2014 \u044d\u0442\u043e \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0438\u043b\u0438 \u0434\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.\n\n\u041f\u043e\u0441\u043b\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u0447\u0430\u0441\u0442\u044c\u044e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.\n\n\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043c\u044b \u043c\u043e\u0436\u0435\u043c \u0438\u0437\u043c\u0435\u043d\u044f\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e, \u043d\u0435 \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043d\u043e\u0432\u0443\u044e.", "es": "Una enmienda es un cambio o una adici\u00f3n oficial a la Constituci\u00f3n.\n\nCuando se aprueba una enmienda, pasa a formar parte de la Constituci\u00f3n.\n\nEsto significa que podemos cambiar la Constituci\u00f3n sin escribir una completamente nueva."}, "There are special steps to change the Constitution.\n\nFirst, a change must be suggested.\n\nThen, 3/4 of the states must agree to the change.\n\nThis means many states must agree before the Constitution can change.": {"ru": "\u0414\u043b\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u043f\u0440\u0435\u0434\u0443\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0430 \u043e\u0441\u043e\u0431\u0430\u044f \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430.\n\n\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442\u044c \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435.\n\n\u0417\u0430\u0442\u0435\u043c \u0442\u0440\u0438 \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u0438 \u0448\u0442\u0430\u0442\u043e\u0432 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u0441\u044f \u0441 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435\u043c.\n\n\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0434\u043b\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u043c\u043d\u043e\u0433\u0438\u0445 \u0448\u0442\u0430\u0442\u043e\u0432.", "es": "Existen pasos especiales para cambiar la Constituci\u00f3n.\n\nPrimero, se debe proponer un cambio.\n\nDespu\u00e9s, tres cuartas partes de los estados deben estar de acuerdo con el cambio.\n\nEsto significa que muchos estados deben estar de acuerdo antes de que pueda cambiarse la Constituci\u00f3n."}, "There are two accepted answers: 'Amendments' and 'The amendment process.'\n\nThey mean the same thing.\n\nThe question asks 'how,' but you do not need to explain all the steps during your citizenship interview.\n\nYou only need to give one of the two accepted answers.": {"ru": "\u0415\u0441\u0442\u044c \u0434\u0432\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u0430: \u00abAmendments\u00bb \u0438 \u00abThe amendment process\u00bb.\n\n\u041e\u043d\u0438 \u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u043e\u0434\u043d\u043e \u0438 \u0442\u043e \u0436\u0435.\n\n\u0412\u043e\u043f\u0440\u043e\u0441 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u043e \u0441\u043b\u043e\u0432\u0430 \u00ab\u043a\u0430\u043a\u00bb, \u043d\u043e \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u0434\u043b\u044f \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u0430 \u043d\u0435 \u043d\u0443\u0436\u043d\u043e \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0442\u044c \u0432\u0441\u0435 \u044d\u0442\u0430\u043f\u044b.\n\n\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u0438\u0437 \u0434\u0432\u0443\u0445 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432.", "es": "Hay dos respuestas aceptadas: \u00abAmendments\u00bb y \u00abThe amendment process\u00bb.\n\nSignifican lo mismo.\n\nLa pregunta dice \u00abc\u00f3mo\u00bb, pero no necesita explicar todos los pasos durante su entrevista de ciudadan\u00eda.\n\nSolo necesita dar una de las dos respuestas aceptadas."}, "Some people think the President can change the Constitution by signing a new law.\n\nBut changing the Constitution is different from making a new law.\n\nThe President does not need to sign or approve amendments to the Constitution.\n\nIf the officer asks how changes are made to the Constitution, you can simply answer, 'Amendments.'": {"ru": "\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0434\u0443\u043c\u0430\u044e\u0442, \u0447\u0442\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u043c\u043e\u0436\u0435\u0442 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e, \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u0432 \u043d\u043e\u0432\u044b\u0439 \u0437\u0430\u043a\u043e\u043d.\n\n\u041d\u043e \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u043e\u0442\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u0430.\n\n\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0443 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u0434\u043f\u0438\u0441\u044b\u0432\u0430\u0442\u044c \u0438\u043b\u0438 \u043e\u0434\u043e\u0431\u0440\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0438 \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.\n\n\u0415\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442, \u043a\u0430\u043a \u0432\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e, \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abAmendments\u00bb.", "es": "Algunas personas creen que el presidente puede cambiar la Constituci\u00f3n firmando una nueva ley.\n\nPero cambiar la Constituci\u00f3n es diferente de aprobar una nueva ley.\n\nEl presidente no necesita firmar ni aprobar las enmiendas a la Constituci\u00f3n.\n\nSi el funcionario pregunta c\u00f3mo se realizan cambios en la Constituci\u00f3n, puede responder simplemente: \u00abAmendments\u00bb."}, "So, if the officer asks you, 'How are changes made to the U.S. Constitution?'\n\nYou only need to give one accepted answer:\n\nAmendments.\n\nThe amendment process.": {"ru": "\u0418\u0442\u0430\u043a, \u0435\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u041a\u0430\u043a \u0432\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0432 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044e \u0421\u0428\u0410?\u00bb\n\n\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0439 \u043e\u0442\u0432\u0435\u0442:\n\n\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0438.\n\n\u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430 \u0432\u043d\u0435\u0441\u0435\u043d\u0438\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a.", "es": "Por tanto, si el funcionario le pregunta: \u00ab\u00bfC\u00f3mo se realizan cambios en la Constituci\u00f3n de Estados Unidos?\u00bb\n\nSolo necesita dar una respuesta aceptada:\n\nEnmiendas.\n\nEl proceso de enmienda."}, "In a direct democracy, people make decisions by voting on them themselves.": {"ru": "\u041f\u0440\u0438 \u043f\u0440\u044f\u043c\u043e\u0439 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438 \u043b\u044e\u0434\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f, \u0441\u0430\u043c\u0438 \u0433\u043e\u043b\u043e\u0441\u0443\u044f \u043f\u043e \u043d\u0438\u043c.", "es": "En una democracia directa, las personas toman decisiones votando sobre ellas mismas."}, "For example, everyone votes to decide whether to build a new playground in their park.": {"ru": "\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u0441\u0435 \u0433\u043e\u043b\u043e\u0441\u0443\u044e\u0442, \u0447\u0442\u043e\u0431\u044b \u0440\u0435\u0448\u0438\u0442\u044c, \u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043b\u0438 \u043d\u043e\u0432\u0443\u044e \u0434\u0435\u0442\u0441\u043a\u0443\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0443 \u0432 \u0441\u0432\u043e\u0451\u043c \u043f\u0430\u0440\u043a\u0435.", "es": "Por ejemplo, todos votan para decidir si se construye un nuevo parque infantil en su parque."}, "In a representative democracy, people choose representatives by voting.": {"ru": "\u041f\u0440\u0438 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0438 \u043b\u044e\u0434\u0438 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u043f\u0443\u0442\u0451\u043c \u0433\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u043d\u0438\u044f.", "es": "En una democracia representativa, las personas eligen representantes mediante el voto."}, "The representatives make many decisions for the people.": {"ru": "\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0438 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u043c\u043d\u043e\u0433\u0438\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0437\u0430 \u043b\u044e\u0434\u0435\u0439.", "es": "Los representantes toman muchas decisiones en nombre de la gente."}, "The United States is a representative democracy.": {"ru": "\u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u2014 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f.", "es": "Estados Unidos es una democracia representativa."}, "Americans elect representatives who make laws for the country.": {"ru": "\u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u044b \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u0437\u0430\u043a\u043e\u043d\u044b \u0434\u043b\u044f \u0441\u0442\u0440\u0430\u043d\u044b.", "es": "Los estadounidenses eligen representantes que hacen las leyes del pa\u00eds."}, "The United States is also a republic.": {"ru": "\u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0428\u0442\u0430\u0442\u044b \u0442\u0430\u043a\u0436\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0439.", "es": "Estados Unidos tambi\u00e9n es una rep\u00fablica."}, "It has no king or queen as head of state.": {"ru": "\u0412\u043e \u0433\u043b\u0430\u0432\u0435 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u043d\u0435 \u0441\u0442\u043e\u0438\u0442 \u043a\u043e\u0440\u043e\u043b\u044c \u0438\u043b\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0430.", "es": "No tiene un rey ni una reina como jefe de Estado."}, "People elect representatives to govern.": {"ru": "\u041b\u044e\u0434\u0438 \u0438\u0437\u0431\u0438\u0440\u0430\u044e\u0442 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u0434\u043b\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0442\u0440\u0430\u043d\u043e\u0439.", "es": "Las personas eligen representantes para gobernar."}, "\u201cDemocracy\u201d alone is too general for this USCIS question.": {"ru": "\u041e\u0434\u043d\u043e\u0433\u043e \u0441\u043b\u043e\u0432\u0430 \u00ab\u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f\u00bb \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e: \u044d\u0442\u043e \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043e\u0431\u0449\u0438\u0439 \u043e\u0442\u0432\u0435\u0442 \u0434\u043b\u044f \u0434\u0430\u043d\u043d\u043e\u0433\u043e \u0432\u043e\u043f\u0440\u043e\u0441\u0430 USCIS.", "es": "\u00abDemocracia\u00bb por s\u00ed sola es demasiado general para esta pregunta de USCIS."}, "Say \u201crepresentative democracy,\u201d or give another officially accepted answer.": {"ru": "\u0421\u043a\u0430\u0436\u0438\u0442\u0435 \u00ab\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f\u00bb \u0438\u043b\u0438 \u0434\u0430\u0439\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u0439 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0439 \u043e\u0442\u0432\u0435\u0442.", "es": "Diga \u00abdemocracia representativa\u00bb o d\u00e9 otra respuesta aceptada oficialmente."}, "The official answers are: Republic.": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043e\u0442\u0432\u0435\u0442\u044b: \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430.", "es": "Las respuestas oficiales son: rep\u00fablica."}, "Constitution-based federal republic.": {"ru": "\u0424\u0435\u0434\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430, \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043d\u0430 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "Rep\u00fablica federal basada en la Constituci\u00f3n."}, "Representative democracy.": {"ru": "\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0434\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u044f.", "es": "Democracia representativa."}, "You only need one.": {"ru": "\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043e\u0434\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430.", "es": "Solo necesita dar una respuesta."}, "The United States has many laws.": {"ru": "\u0412 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445 \u043c\u043d\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u043e\u0432.", "es": "Estados Unidos tiene muchas leyes."}, "Laws are rules that people must follow.": {"ru": "\u0417\u0430\u043a\u043e\u043d\u044b \u2014 \u044d\u0442\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u043b\u044e\u0434\u0438 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c.", "es": "Las leyes son reglas que las personas deben cumplir."}, "But one law is more important than all the others.": {"ru": "\u041d\u043e \u043e\u0434\u0438\u043d \u0437\u0430\u043a\u043e\u043d \u0432\u0430\u0436\u043d\u0435\u0435 \u0432\u0441\u0435\u0445 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445.", "es": "Pero una ley es m\u00e1s importante que todas las dem\u00e1s."}, "It is the U.S. Constitution.": {"ru": "\u042d\u0442\u043e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410.", "es": "Es la Constituci\u00f3n de Estados Unidos."}, "The Constitution is the supreme law of the land.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u2014 \u0432\u044b\u0441\u0448\u0438\u0439 \u0437\u0430\u043a\u043e\u043d \u0441\u0442\u0440\u0430\u043d\u044b.", "es": "La Constituci\u00f3n es la ley suprema del pa\u00eds."}, "This means that other laws cannot go against it.": {"ru": "\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u0434\u0440\u0443\u0433\u0438\u0435 \u0437\u0430\u043a\u043e\u043d\u044b \u043d\u0435 \u043c\u043e\u0433\u0443\u0442 \u0435\u0439 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0438\u0442\u044c.", "es": "Esto significa que otras leyes no pueden contradecirla."}, "Some people answer this question with the Bill of Rights or the Declaration of Independence.": {"ru": "\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043b\u044e\u0434\u0438 \u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0442 \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u00ab\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445\u00bb \u0438\u043b\u0438 \u00ab\u0414\u0435\u043a\u043b\u0430\u0440\u0430\u0446\u0438\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438\u00bb.", "es": "Algunas personas responden a esta pregunta con \u00abla Carta de Derechos\u00bb o \u00abla Declaraci\u00f3n de Independencia\u00bb."}, "These are important documents, but they are not the correct answer to this question.": {"ru": "\u042d\u0442\u043e \u0432\u0430\u0436\u043d\u044b\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b, \u043d\u043e \u043e\u043d\u0438 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u043c \u043e\u0442\u0432\u0435\u0442\u043e\u043c \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441.", "es": "Estos son documentos importantes, pero no son la respuesta correcta a esta pregunta."}, "The Bill of Rights is part of the Constitution.": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0447\u0430\u0441\u0442\u044c\u044e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438.", "es": "La Carta de Derechos forma parte de la Constituci\u00f3n."}, "The correct answer is the U.S. Constitution.": {"ru": "\u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u2014 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0421\u0428\u0410.", "es": "La respuesta correcta es la Constituci\u00f3n de Estados Unidos."}, "The word \u2018constitute\u2019 means \u2018to form\u2019 or \u2018to make up.\u2019": {"ru": "\u0421\u043b\u043e\u0432\u043e constitute \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u00ab\u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c\u00bb \u0438\u043b\u0438 \u00ab\u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c\u00bb.", "es": "La palabra constitute significa \u00abformar\u00bb o \u00abcomponer\u00bb."}, "This can help you remember one important job of the Constitution: it forms the government.": {"ru": "\u042d\u0442\u043e \u043f\u043e\u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u044c \u043e\u0434\u043d\u0443 \u0432\u0430\u0436\u043d\u0443\u044e \u0444\u0443\u043d\u043a\u0446\u0438\u044e \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438: \u043e\u043d\u0430 \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0432\u043b\u0430\u0441\u0442\u0438.", "es": "Esto puede ayudarle a recordar una funci\u00f3n importante de la Constituci\u00f3n: establece el gobierno."}, "The Constitution establishes the U.S. government.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0421\u0428\u0410.", "es": "La Constituci\u00f3n establece el gobierno de Estados Unidos."}, "It also defines its three branches: legislative, executive, and judicial.": {"ru": "\u041e\u043d\u0430 \u0442\u0430\u043a\u0436\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u0442\u0440\u0438 \u0432\u0435\u0442\u0432\u0438 \u0432\u043b\u0430\u0441\u0442\u0438: \u0437\u0430\u043a\u043e\u043d\u043e\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u0443\u044e, \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u0438 \u0441\u0443\u0434\u0435\u0431\u043d\u0443\u044e.", "es": "Tambi\u00e9n define sus tres poderes: legislativo, ejecutivo y judicial."}, "The Constitution forms the government, defines its parts and powers, and protects people's rights.": {"ru": "\u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f \u0443\u0447\u0440\u0435\u0436\u0434\u0430\u0435\u0442 \u043e\u0440\u0433\u0430\u043d\u044b \u0432\u043b\u0430\u0441\u0442\u0438, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u0438\u0445 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0438 \u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0438\u044f \u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439.", "es": "La Constituci\u00f3n establece el gobierno, define sus partes y facultades, y protege los derechos de las personas."}, "At your citizenship interview, you only need to name one of these things.": {"ru": "\u041d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043d\u0430\u0437\u0432\u0430\u0442\u044c \u043e\u0434\u043d\u0443 \u0438\u0437 \u044d\u0442\u0438\u0445 \u0444\u0443\u043d\u043a\u0446\u0438\u0439.", "es": "En su entrevista de ciudadan\u00eda solo necesita nombrar una de estas funciones."}, "What does the Bill of Rights protect?": {"ru": "\u0427\u0442\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445?", "es": "\u00bfQu\u00e9 protege la Carta de Derechos?"}, "(The basic) rights of Americans": {"ru": "(\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435) \u043f\u0440\u0430\u0432\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u0435\u0432", "es": "Los derechos (b\u00e1sicos) de los estadounidenses"}, "(The basic) rights of people living in the United States": {"ru": "(\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435) \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439, \u0436\u0438\u0432\u0443\u0449\u0438\u0445 \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445", "es": "Los derechos (b\u00e1sicos) de las personas que viven en Estados Unidos"}, "Words in parentheses ( ) are optional. You can include them or leave them out.": {"ru": "\u0421\u043b\u043e\u0432\u0430 \u0432 \u0441\u043a\u043e\u0431\u043a\u0430\u0445 ( ) \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b. \u0418\u0445 \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0438\u0437\u043d\u0435\u0441\u0442\u0438 \u0438\u043b\u0438 \u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c.", "es": "Las palabras entre par\u00e9ntesis ( ) son opcionales. Puede incluirlas u omitirlas."}, "Official USCIS Question #6": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 USCIS \u2116 6", "es": "Pregunta oficial de USCIS n.\u00ba 6"}, "The word \"bill\" can mean a written list of proposed laws or rights.": {"ru": "\u0421\u043b\u043e\u0432\u043e bill \u043c\u043e\u0436\u0435\u0442 \u043e\u0437\u043d\u0430\u0447\u0430\u0442\u044c \u043f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0445 \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0438\u043b\u0438 \u043f\u0440\u0430\u0432.", "es": "La palabra bill puede significar una lista escrita de leyes o derechos propuestos."}, "The Bill of Rights is a list of important rights that the Constitution protects.": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u2014 \u044d\u0442\u043e \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u0432\u0430\u0436\u043d\u044b\u0445 \u043f\u0440\u0430\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f.", "es": "La Carta de Derechos es una lista de derechos importantes que protege la Constituci\u00f3n."}, "It includes the first ten amendments to the U.S. Constitution.": {"ru": "\u041e\u043d \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043f\u0435\u0440\u0432\u044b\u0435 \u0434\u0435\u0441\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u0421\u0428\u0410.", "es": "Incluye las primeras diez enmiendas a la Constituci\u00f3n de Estados Unidos."}, "What Rights Does It Protect?": {"ru": "\u041a\u0430\u043a\u0438\u0435 \u043f\u0440\u0430\u0432\u0430 \u043e\u043d \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442?", "es": "\u00bfQu\u00e9 derechos protege?"}, "The Bill of Rights protects people's basic rights and freedoms.": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u043b\u044e\u0434\u0435\u0439.", "es": "La Carta de Derechos protege los derechos y las libertades b\u00e1sicos de las personas."}, "For example, it protects freedom of speech.": {"ru": "\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043e\u043d \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0441\u043b\u043e\u0432\u0430.", "es": "Por ejemplo, protege la libertad de expresi\u00f3n."}, "This means people can express their opinions.": {"ru": "\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u0432\u044b\u0440\u0430\u0436\u0430\u0442\u044c \u0441\u0432\u043e\u0451 \u043c\u043d\u0435\u043d\u0438\u0435.", "es": "Esto significa que las personas pueden expresar sus opiniones."}, "It also protects freedom of religion.": {"ru": "\u041e\u043d \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f.", "es": "Tambi\u00e9n protege la libertad de religi\u00f3n."}, "This means people can choose their religion or choose not to follow a religion.": {"ru": "\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u0432\u044b\u0431\u0438\u0440\u0430\u0442\u044c \u0441\u0432\u043e\u044e \u0440\u0435\u043b\u0438\u0433\u0438\u044e \u0438\u043b\u0438 \u043d\u0435 \u0438\u0441\u043f\u043e\u0432\u0435\u0434\u043e\u0432\u0430\u0442\u044c \u043d\u0438\u043a\u0430\u043a\u043e\u0439 \u0440\u0435\u043b\u0438\u0433\u0438\u0438.", "es": "Esto significa que las personas pueden elegir su religi\u00f3n o decidir no seguir ninguna religi\u00f3n."}, "These are just two examples of the rights protected by the Bill of Rights.": {"ru": "\u042d\u0442\u043e \u043b\u0438\u0448\u044c \u0434\u0432\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u0430 \u043f\u0440\u0430\u0432, \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u043c\u044b\u0445 \u0411\u0438\u043b\u043b\u0435\u043c \u043e \u043f\u0440\u0430\u0432\u0430\u0445.", "es": "Estos son solo dos ejemplos de los derechos protegidos por la Carta de Derechos."}, "Whose Rights Does the Bill of Rights Protect?": {"ru": "\u0427\u044c\u0438 \u043f\u0440\u0430\u0432\u0430 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445?", "es": "\u00bfDe qui\u00e9n protege los derechos la Carta de Derechos?"}, "The Bill of Rights protects the basic rights of Americans.": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u0435\u0432.", "es": "La Carta de Derechos protege los derechos b\u00e1sicos de los estadounidenses."}, "But you do not have to be an American citizen to have many of these rights.": {"ru": "\u041d\u043e \u0434\u043b\u044f \u043e\u0431\u043b\u0430\u0434\u0430\u043d\u0438\u044f \u043c\u043d\u043e\u0433\u0438\u043c\u0438 \u0438\u0437 \u044d\u0442\u0438\u0445 \u043f\u0440\u0430\u0432 \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0431\u044b\u0442\u044c \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0438\u043d\u043e\u043c \u0421\u0428\u0410.", "es": "Pero no es necesario ser ciudadano estadounidense para tener muchos de estos derechos."}, "Many rights in the Bill of Rights also protect people who live in the United States but are not U.S. citizens.": {"ru": "\u041c\u043d\u043e\u0433\u0438\u0435 \u043f\u0440\u0430\u0432\u0430, \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u044b\u0435 \u0432 \u0411\u0438\u043b\u043b\u0435 \u043e \u043f\u0440\u0430\u0432\u0430\u0445, \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u044e\u0442 \u043b\u044e\u0434\u0435\u0439, \u0436\u0438\u0432\u0443\u0449\u0438\u0445 \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0430\u043c\u0438 \u0421\u0428\u0410.", "es": "Muchos derechos de la Carta de Derechos tambi\u00e9n protegen a las personas que viven en Estados Unidos, pero no son ciudadanos estadounidenses."}, "That is why both answers are accepted in the citizenship interview.": {"ru": "\u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442\u0441\u044f \u043e\u0431\u0430 \u043e\u0442\u0432\u0435\u0442\u0430.", "es": "Por eso se aceptan ambas respuestas en la entrevista de ciudadan\u00eda."}, "There are two accepted answers:": {"ru": "\u0415\u0441\u0442\u044c \u0434\u0432\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u0430:", "es": "Hay dos respuestas aceptadas:"}, "\"The basic rights of Americans\" or \"The basic rights of people living in the United States.\"": {"ru": "\u00abThe basic rights of Americans\u00bb \u0438\u043b\u0438 \u00abThe basic rights of people living in the United States\u00bb.", "es": "\u00abThe basic rights of Americans\u00bb o \u00abThe basic rights of people living in the United States\u00bb."}, "In the official answers, \"the basic\" is in parentheses.": {"ru": "\u0412 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u0430\u0445 \u0441\u043b\u043e\u0432\u0430 the basic \u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u0432 \u0441\u043a\u043e\u0431\u043a\u0438.", "es": "En las respuestas oficiales, the basic est\u00e1 entre par\u00e9ntesis."}, "This means these words are optional.": {"ru": "\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u044d\u0442\u0438 \u0441\u043b\u043e\u0432\u0430 \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b.", "es": "Esto significa que estas palabras son opcionales."}, "You don't need to name specific rights or explain the amendments.": {"ru": "\u041d\u0435 \u043d\u0443\u0436\u043d\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0438\u043b\u0438 \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0438.", "es": "No necesita nombrar derechos espec\u00edficos ni explicar las enmiendas."}, "Just give one of the two accepted answers.": {"ru": "\u041f\u0440\u043e\u0441\u0442\u043e \u0434\u0430\u0439\u0442\u0435 \u043e\u0434\u0438\u043d \u0438\u0437 \u0434\u0432\u0443\u0445 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432.", "es": "Solo d\u00e9 una de las dos respuestas aceptadas."}, "Some people answer this question by saying \"Freedom of speech\" or \"Freedom of religion.\"": {"ru": "\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0442 \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u00ab\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0441\u043b\u043e\u0432\u0430\u00bb \u0438\u043b\u0438 \u00ab\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f\u00bb.", "es": "Algunas personas responden a esta pregunta diciendo \u00abLibertad de expresi\u00f3n\u00bb o \u00abLibertad de religi\u00f3n\u00bb."}, "These are examples of rights protected by the Bill of Rights, but they are not accepted answers to this question.": {"ru": "\u042d\u0442\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u044b \u043f\u0440\u0430\u0432, \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u043c\u044b\u0445 \u0411\u0438\u043b\u043b\u0435\u043c \u043e \u043f\u0440\u0430\u0432\u0430\u0445, \u043d\u043e \u043e\u043d\u0438 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u043c\u0438 \u043e\u0442\u0432\u0435\u0442\u0430\u043c\u0438 \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441.", "es": "Estos son ejemplos de derechos protegidos por la Carta de Derechos, pero no son respuestas aceptadas para esta pregunta."}, "The question asks what the Bill of Rights protects in general.": {"ru": "\u0412\u043e\u043f\u0440\u043e\u0441 \u043e \u0442\u043e\u043c, \u0447\u0442\u043e \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0432 \u0446\u0435\u043b\u043e\u043c.", "es": "La pregunta pide qu\u00e9 protege la Carta de Derechos en general."}, "You can simply answer, \"The rights of Americans.\"": {"ru": "\u041c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abThe rights of Americans\u00bb.", "es": "Puede responder simplemente: \u00abThe rights of Americans\u00bb."}, "Official Question and Answers": {"ru": "\u041e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u0438 \u043e\u0442\u0432\u0435\u0442\u044b", "es": "Pregunta oficial y respuestas"}, "So, if the officer asks you, \u201cWhat does the Bill of Rights protect?\u201d": {"ru": "\u0418\u0442\u0430\u043a, \u0435\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u0427\u0442\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445?\u00bb", "es": "Por tanto, si el funcionario le pregunta: \u00ab\u00bfQu\u00e9 protege la Carta de Derechos?\u00bb"}, "\u201cThe basic rights of Americans.\u201d": {"ru": "\u00ab\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u0435\u0432\u00bb.", "es": "\u00abLos derechos b\u00e1sicos de los estadounidenses\u00bb."}, "Or:": {"ru": "\u0418\u043b\u0438:", "es": "O bien:"}, "\u201cThe basic rights of people living in the United States.\u201d": {"ru": "\u00ab\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439, \u0436\u0438\u0432\u0443\u0449\u0438\u0445 \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445\u00bb.", "es": "\u00abLos derechos b\u00e1sicos de las personas que viven en Estados Unidos\u00bb."}, "Bill (noun)": {"ru": "\u0411\u0438\u043b\u043b\u044c (\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435)", "es": "Proyecto de ley (sustantivo)"}, "A written list of proposed laws or rights.": {"ru": "\u041f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0445 \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0438\u043b\u0438 \u043f\u0440\u0430\u0432.", "es": "Una lista escrita de leyes o derechos propuestos."}, "Bill of Rights": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445", "es": "Carta de Derechos"}, "The first ten amendments to the U.S. Constitution.": {"ru": "\u041f\u0435\u0440\u0432\u044b\u0435 \u0434\u0435\u0441\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u0421\u0428\u0410.", "es": "Las primeras diez enmiendas a la Constituci\u00f3n de Estados Unidos."}, "Protect (verb)": {"ru": "\u0417\u0430\u0449\u0438\u0449\u0430\u0442\u044c (\u0433\u043b\u0430\u0433\u043e\u043b)", "es": "Proteger (verbo)"}, "To keep someone or something safe.": {"ru": "\u0417\u0430\u0449\u0438\u0449\u0430\u0442\u044c \u043a\u043e\u0433\u043e-\u043b\u0438\u0431\u043e \u0438\u043b\u0438 \u0447\u0442\u043e-\u043b\u0438\u0431\u043e.", "es": "Mantener a alguien o algo a salvo."}, "Right (noun)": {"ru": "\u041f\u0440\u0430\u0432\u043e (\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435)", "es": "Derecho (sustantivo)"}, "Something a person is allowed to do or have by law.": {"ru": "\u0422\u043e, \u0447\u0442\u043e \u0447\u0435\u043b\u043e\u0432\u0435\u043a \u0432\u043f\u0440\u0430\u0432\u0435 \u0434\u0435\u043b\u0430\u0442\u044c \u0438\u043b\u0438 \u0438\u043c\u0435\u0442\u044c \u043f\u043e \u0437\u0430\u043a\u043e\u043d\u0443.", "es": "Algo que una persona puede hacer o tener por ley."}, "Freedom of Speech": {"ru": "\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0441\u043b\u043e\u0432\u0430", "es": "Libertad de expresi\u00f3n"}, "Freedom of Religion": {"ru": "\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f", "es": "Libertad de religi\u00f3n"}, "The word \"bill\" can mean a written list of proposed laws or rights.\n\nThe Bill of Rights is a list of important rights that the Constitution protects.\n\nIt includes the first ten amendments to the U.S. Constitution.": {"ru": "\u0421\u043b\u043e\u0432\u043e bill \u043c\u043e\u0436\u0435\u0442 \u043e\u0437\u043d\u0430\u0447\u0430\u0442\u044c \u043f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0445 \u0437\u0430\u043a\u043e\u043d\u043e\u0432 \u0438\u043b\u0438 \u043f\u0440\u0430\u0432.\n\n\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u2014 \u044d\u0442\u043e \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u0432\u0430\u0436\u043d\u044b\u0445 \u043f\u0440\u0430\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u044f.\n\n\u041e\u043d \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043f\u0435\u0440\u0432\u044b\u0435 \u0434\u0435\u0441\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043e\u043a \u043a \u041a\u043e\u043d\u0441\u0442\u0438\u0442\u0443\u0446\u0438\u0438 \u0421\u0428\u0410.", "es": "La palabra bill puede significar una lista escrita de leyes o derechos propuestos.\n\nLa Carta de Derechos es una lista de derechos importantes que protege la Constituci\u00f3n.\n\nIncluye las primeras diez enmiendas a la Constituci\u00f3n de Estados Unidos."}, "The Bill of Rights protects people's basic rights and freedoms.\n\nFor example, it protects freedom of speech.\n\nThis means people can express their opinions.\n\nIt also protects freedom of religion.\n\nThis means people can choose their religion or choose not to follow a religion.\n\nThese are just two examples of the rights protected by the Bill of Rights.": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u043b\u044e\u0434\u0435\u0439.\n\n\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043e\u043d \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0441\u043b\u043e\u0432\u0430.\n\n\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u0432\u044b\u0440\u0430\u0436\u0430\u0442\u044c \u0441\u0432\u043e\u0451 \u043c\u043d\u0435\u043d\u0438\u0435.\n\n\u041e\u043d \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u0443 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f.\n\n\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u0432\u044b\u0431\u0438\u0440\u0430\u0442\u044c \u0441\u0432\u043e\u044e \u0440\u0435\u043b\u0438\u0433\u0438\u044e \u0438\u043b\u0438 \u043d\u0435 \u0438\u0441\u043f\u043e\u0432\u0435\u0434\u043e\u0432\u0430\u0442\u044c \u043d\u0438\u043a\u0430\u043a\u043e\u0439 \u0440\u0435\u043b\u0438\u0433\u0438\u0438.\n\n\u042d\u0442\u043e \u043b\u0438\u0448\u044c \u0434\u0432\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u0430 \u043f\u0440\u0430\u0432, \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u043c\u044b\u0445 \u0411\u0438\u043b\u043b\u0435\u043c \u043e \u043f\u0440\u0430\u0432\u0430\u0445.", "es": "La Carta de Derechos protege los derechos y las libertades b\u00e1sicos de las personas.\n\nPor ejemplo, protege la libertad de expresi\u00f3n.\n\nEsto significa que las personas pueden expresar sus opiniones.\n\nTambi\u00e9n protege la libertad de religi\u00f3n.\n\nEsto significa que las personas pueden elegir su religi\u00f3n o decidir no seguir ninguna religi\u00f3n.\n\nEstos son solo dos ejemplos de los derechos protegidos por la Carta de Derechos."}, "The Bill of Rights protects the basic rights of Americans.\n\nBut you do not have to be an American citizen to have many of these rights.\n\nMany rights in the Bill of Rights also protect people who live in the United States but are not U.S. citizens.\n\nThat is why both answers are accepted in the citizenship interview.": {"ru": "\u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u0435\u0432.\n\n\u041d\u043e \u0434\u043b\u044f \u043e\u0431\u043b\u0430\u0434\u0430\u043d\u0438\u044f \u043c\u043d\u043e\u0433\u0438\u043c\u0438 \u0438\u0437 \u044d\u0442\u0438\u0445 \u043f\u0440\u0430\u0432 \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0431\u044b\u0442\u044c \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0438\u043d\u043e\u043c \u0421\u0428\u0410.\n\n\u041c\u043d\u043e\u0433\u0438\u0435 \u043f\u0440\u0430\u0432\u0430, \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u044b\u0435 \u0432 \u0411\u0438\u043b\u043b\u0435 \u043e \u043f\u0440\u0430\u0432\u0430\u0445, \u0442\u0430\u043a\u0436\u0435 \u0437\u0430\u0449\u0438\u0449\u0430\u044e\u0442 \u043b\u044e\u0434\u0435\u0439, \u0436\u0438\u0432\u0443\u0449\u0438\u0445 \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0430\u043c\u0438 \u0421\u0428\u0410.\n\n\u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0430 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442\u0441\u044f \u043e\u0431\u0430 \u043e\u0442\u0432\u0435\u0442\u0430.", "es": "La Carta de Derechos protege los derechos b\u00e1sicos de los estadounidenses.\n\nPero no es necesario ser ciudadano estadounidense para tener muchos de estos derechos.\n\nMuchos derechos de la Carta de Derechos tambi\u00e9n protegen a las personas que viven en Estados Unidos, pero no son ciudadanos estadounidenses.\n\nPor eso se aceptan ambas respuestas en la entrevista de ciudadan\u00eda."}, "There are two accepted answers:\n\n\"The basic rights of Americans\" or \"The basic rights of people living in the United States.\"\n\nIn the official answers, \"the basic\" is in parentheses.\n\nThis means these words are optional.\n\nYou don't need to name specific rights or explain the amendments.\n\nJust give one of the two accepted answers.": {"ru": "\u0415\u0441\u0442\u044c \u0434\u0432\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u0430:\n\n\u00abThe basic rights of Americans\u00bb \u0438\u043b\u0438 \u00abThe basic rights of people living in the United States\u00bb.\n\n\u0412 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u0430\u0445 \u0441\u043b\u043e\u0432\u0430 the basic \u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u0432 \u0441\u043a\u043e\u0431\u043a\u0438.\n\n\u042d\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u044d\u0442\u0438 \u0441\u043b\u043e\u0432\u0430 \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b.\n\n\u041d\u0435 \u043d\u0443\u0436\u043d\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0438\u043b\u0438 \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0442\u044c \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0438.\n\n\u041f\u0440\u043e\u0441\u0442\u043e \u0434\u0430\u0439\u0442\u0435 \u043e\u0434\u0438\u043d \u0438\u0437 \u0434\u0432\u0443\u0445 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432.", "es": "Hay dos respuestas aceptadas:\n\n\u00abThe basic rights of Americans\u00bb o \u00abThe basic rights of people living in the United States\u00bb.\n\nEn las respuestas oficiales, the basic est\u00e1 entre par\u00e9ntesis.\n\nEsto significa que estas palabras son opcionales.\n\nNo necesita nombrar derechos espec\u00edficos ni explicar las enmiendas.\n\nSolo d\u00e9 una de las dos respuestas aceptadas."}, "Some people answer this question by saying \"Freedom of speech\" or \"Freedom of religion.\"\n\nThese are examples of rights protected by the Bill of Rights, but they are not accepted answers to this question.\n\nThe question asks what the Bill of Rights protects in general.\n\nYou can simply answer, \"The rights of Americans.\"": {"ru": "\u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0442 \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u00ab\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0441\u043b\u043e\u0432\u0430\u00bb \u0438\u043b\u0438 \u00ab\u0421\u0432\u043e\u0431\u043e\u0434\u0430 \u0432\u0435\u0440\u043e\u0438\u0441\u043f\u043e\u0432\u0435\u0434\u0430\u043d\u0438\u044f\u00bb.\n\n\u042d\u0442\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u044b \u043f\u0440\u0430\u0432, \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u043c\u044b\u0445 \u0411\u0438\u043b\u043b\u0435\u043c \u043e \u043f\u0440\u0430\u0432\u0430\u0445, \u043d\u043e \u043e\u043d\u0438 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u043c\u0438 \u043e\u0442\u0432\u0435\u0442\u0430\u043c\u0438 \u043d\u0430 \u044d\u0442\u043e\u0442 \u0432\u043e\u043f\u0440\u043e\u0441.\n\n\u0412\u043e\u043f\u0440\u043e\u0441 \u043e \u0442\u043e\u043c, \u0447\u0442\u043e \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0432 \u0446\u0435\u043b\u043e\u043c.\n\n\u041c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c: \u00abThe rights of Americans\u00bb.", "es": "Algunas personas responden a esta pregunta diciendo \u00abLibertad de expresi\u00f3n\u00bb o \u00abLibertad de religi\u00f3n\u00bb.\n\nEstos son ejemplos de derechos protegidos por la Carta de Derechos, pero no son respuestas aceptadas para esta pregunta.\n\nLa pregunta pide qu\u00e9 protege la Carta de Derechos en general.\n\nPuede responder simplemente: \u00abThe rights of Americans\u00bb."}, "So, if the officer asks you, \u201cWhat does the Bill of Rights protect?\u201d\n\nYou only need to give one accepted answer:\n\n\u201cThe basic rights of Americans.\u201d\n\nOr:\n\n\u201cThe basic rights of people living in the United States.\u201d": {"ru": "\u0418\u0442\u0430\u043a, \u0435\u0441\u043b\u0438 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a \u0441\u043f\u0440\u043e\u0441\u0438\u0442: \u00ab\u0427\u0442\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0411\u0438\u043b\u043b\u044c \u043e \u043f\u0440\u0430\u0432\u0430\u0445?\u00bb\n\n\u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0439 \u043e\u0442\u0432\u0435\u0442:\n\n\u00ab\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0446\u0435\u0432\u00bb.\n\n\u0418\u043b\u0438:\n\n\u00ab\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u043b\u044e\u0434\u0435\u0439, \u0436\u0438\u0432\u0443\u0449\u0438\u0445 \u0432 \u0421\u043e\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u0430\u0445\u00bb.", "es": "Por tanto, si el funcionario le pregunta: \u00ab\u00bfQu\u00e9 protege la Carta de Derechos?\u00bb\n\nSolo necesita dar una respuesta aceptada:\n\n\u00abLos derechos b\u00e1sicos de los estadounidenses\u00bb.\n\nO bien:\n\n\u00abLos derechos b\u00e1sicos de las personas que viven en Estados Unidos\u00bb."}};

let q1LessonLanguage='en',q1CaptionObserver=null;
