 scope.querySelectorAll('[data-q1-asset]').forEach(figure=>{const keys=labelKeys[figure.dataset.q1Asset];if(!keys)return;const text=document.createElement('div');text.className='q1-art-label-translations';text.lang=q1LessonLanguage;text.textContent=keys.map(k=>q1Translations[k][q1LessonLanguage]).join(' · ');if(figure.classList.contains('q1-video-picture'))figure.after(text);else figure.appendChild(text);});
