function applyQ1Translations(){if(!lessons[state.current])return;applyQ1ScopeTranslations($('learn'));const root=currentLessonPlayerRoot();if(!root)return;applyQ1ScopeTranslations(root);root.querySelector('.q1-caption-translation')?.remove();if(q1LessonLanguage!=='en'&&currentLesson().mode==='learn'){const caption=root.getElementById('caption'),text=q1Translations[caption.textContent]?.[q1LessonLanguage];if(text){const translated=document.createElement('div');translated.className='q1-caption-translation';translated.lang=q1LessonLanguage;translated.textContent=text;caption.after(translated);}}}
function setupQ1Language(){const caption=currentLessonPlayerRoot()?.getElementById('caption');if(caption){q1CaptionObserver=new MutationObserver(()=>applyQ1Translations());q1CaptionObserver.observe(caption,{childList:true,characterData:true,subtree:true});}applyQ1Translations();}
