const validAnswerBeforeQ4=validAnswer;
validAnswer=function(value,q){if(q!==4)return validAnswerBeforeQ4(value,q);let v=normalize(value).replace(/\b(a|an|the)\b/g,'').replace(/\s+/g,' ').trim();v=v.replace(/^example of /,'');const variants=['self government','selfgovernment','popular sovereignty','consent of governed','people should govern themselves','social contract'];return variants.some(answer=>{const a=answer.split(' '),b=v.split(' ');return a.length===b.length&&a.every((word,i)=>word===b[i]||(word.length>=5&&b[i].length>=4&&editDistance(word,b[i])<=1));});};
