function newQ4Practice(){const learned=Object.keys(lessons).map(Number).filter(q=>q<4&&state.lessons[q].completed);const ranked=shuffle(learned).sort((a,b)=>{const x=state.practiceHistory[a]||{},y=state.practiceHistory[b]||{};return (y.incorrect||0)-(x.incorrect||0)||(x.lastPracticed||0)-(y.lastPracticed||0);});let chosen=ranked.slice(0,4);const prior=state.q4Practice;if(prior&&chosen.length>1&&chosen.join()===prior.ids.slice(1).join())chosen=chosen.slice(1).concat(chosen[0]);state.q4Practice={ids:[4,...chosen],index:0,answers:{},complete:false};}
function renderQ4Practice(){if(!state.q4Practice)newQ4Practice();renderModePractice({kind:'q4',session:state.q4Practice});}
const modeBeforeQ4=setMode;
setMode=function(mode,scroll=true){if(state.current!==4)return modeBeforeQ4(mode,scroll);stopSpeech();currentLesson().mode=mode;$('learn').classList.toggle('hidden',mode!=='learn');$('practice').classList.add('hidden');$('activity-question').classList.add('hidden');$('review').classList.toggle('hidden',mode==='learn');if(mode==='practice')renderQ4Practice();save();if(scroll)topOfLesson();};
const mountBeforeQ4=mountLesson;
mountLesson=function(){q4ContentFitCleanup?.();q4ContentFitCleanup=null;if(state.current!==4)return mountBeforeQ4();q1FrameCleanup?.();q1FrameCleanup=null;q1CaptionObserver?.disconnect();q1CaptionObserver=null;q1PlayerUIObserver?.disconnect();stopSpeech();document.querySelector('.main').classList.remove('q2-simple','q3-simple');document.querySelector('.main').classList.add('q1-simple');updateNavigation();document.querySelector('.tabs').classList.add('hidden');$('practice').classList.add('hidden');$('review').classList.add('hidden');$('activity-question').classList.add('hidden');$('learn').innerHTML=`<h2 class="official-question-heading q4-page-question">${q2AudioButton(lessons[4].question)}</h2><section class="official-answer-panel"><p class="answer-panel-title">Official accepted answers</p><ul class="official-answers">${lessons[4].answers.map(a=>'<li>'+q2AudioButton(a,true)+'</li>').join('')}</ul><p>You only need to give one answer in the interview.</p><p class="audio-status help" id="official-audio-status" role="status"></p></section><details class="q1-words"><summary><span>Words to Know</span><small>Optional · Tap to expand or collapse</small></summary>${q4Vocabulary}</details><h2>Understand the Answer</h2><div id="q4-cartoon" class="q1-cartoon" role="region" aria-label="Ten-scene explanation of We the People"></div><aside class="q4-key-takeaway"><h3>Key Takeaway</h3><p>“We the People” means that political power belongs to the people, not to a ruler or the government itself.</p></aside><button id="q4-start" class="primary q1-start">Start Practice</button>`;mountCoursePlayer($('q4-cartoon'),q4CartoonDocument);bindLearningAudio();$('q4-start').onclick=()=>{newQ4Practice();setMode('practice');};setupQ1Language();stabilizeQ1Frame();setupQ4ContentFit();const root=currentLessonPlayerRoot();q1PlayerUIObserver=new MutationObserver(scheduleCourseUI);q1PlayerUIObserver.observe(root,{childList:true,characterData:true,subtree:true});localizeCourseUI();setMode(currentLesson().mode,false);};
