 chapters.forEach((b,i)=>b.onclick=()=>select(i));audio.onended=()=>{if(running)advance();};audio.onplay=()=>{running=true;get('play').textContent='Ⅱ Pause';};audio.onpause=()=>{get('play').textContent='▶ Play';};audio.onerror=()=>{status.textContent='The audio could not be loaded.';};
 get('play').onclick=()=>running?pause():play();get('restart').onclick=()=>{select(0);play();};get('seek').oninput=()=>select(Number(get('seek').value));get('voice').onchange=()=>{const resume=running;stop();showPart();if(resume)play();};
